-- D-23 ISSUE: FSQM-027 Allergen Management Program and FRM-916 Allergen Cleaning Verification Record.
-- Approved GJM, effective 2026-10-29. First issue: revision "New".
--
-- Issued before an allergen test kit is chosen, with the open items stated and dated (reverses the
-- 2026-10-07 decision to wait for the kit; confirmed by GJM's approval of this change). Owner, 2026-10-29:
-- the other customer's packs say "manufactured in a facility that processes tree nuts, peanuts", so the
-- yearly verification swab covers every product. 2.8.1.7 and 2.8.1.10 cited on the lines that meet them;
-- 2.8.1.11 declared not applicable (content.not_applicable). Same transaction: SOP-204 archived (replaced,
-- never issued), schedule row allergen_swab_verification (yearly, FRM-916, first due 2027-01-31),
-- FSQM-017 v21 listing it, FSQM-016 v5 (two lines that called FSQM-027 a draft).
-- Guarded on the md5 of each document as read from production on 2026-10-29.

begin;

do $guard$
declare h text;
begin
  select md5(content::text) into h from public.sop_documents where sop_number = 'FSQM-027' and status = 'draft';
  if h is distinct from 'eb4a1dad93b4a2839569b9abedaeb27d' then raise exception 'FSQM-027 is not the draft that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'FRM-916' and status = 'draft';
  if h is distinct from '6dd6bc8a8fe5f7b33adb1c00c4c53c6a' then raise exception 'FRM-916 is not the draft that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'SOP-204' and status = 'draft';
  if h is distinct from '89b7495d0b8d5e7f591a73e1916124d8' then raise exception 'SOP-204 is not the draft that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'FSQM-016' and status = 'active' and revision = 'v4';
  if h is distinct from '7f95b14165509853d7c0ff39de8b87c1' then raise exception 'FSQM-016 is not the v4 that was read (md5 %).', h; end if;
  select md5(content::text) into h from public.sop_documents where sop_number = 'FSQM-017' and status = 'active' and revision = 'v20';
  if h is distinct from '916aa7d992f52061655778c69e41e5fe' then raise exception 'FSQM-017 is not the v20 that was read (md5 %).', h; end if;
  if exists (select 1 from public.verification_schedule where activity_key = 'allergen_swab_verification') then
    raise exception 'an allergen_swab_verification schedule row already exists.';
  end if;
end $guard$;

update public.sop_documents set content = $jx${"scope": "Every ingredient, processing aid and lubricant, every product made on site, and everyone who enters the production and storage rooms.", "purpose": "This program states how Adventure Bakery keeps an allergen out of any product that does not declare it: which allergens are on site, where they are kept, the order products are made in, the clean between them, and how that clean is proved.", "records": "• FRM-916 - one per validation or verification swab session\n• The machine cleaning logs, FRM-909 to FRM-912, with the allergen changeover ticked\n• FRM-207 - the allergens of every material\n• FRM-903 and FRM-913 - segregation checks\n• Training records for TRN-003, TRN-004 and TRN-004A in the Team Portal", "procedure": ["The allergens", "• The list used is the nine major food allergens of the United States, where the product is made and sold: milk, egg, fish, crustacean shellfish, tree nuts, peanuts, wheat, soy and sesame (SQF 2.8.1.1 iii).", "• On this site: wheat, milk, egg, soy and three tree nuts - pecans, walnuts and almonds. Not on this site, and not brought in without this program being revised first: any other tree nut, peanuts, sesame, fish and crustacean shellfish.", "• The list of allergens, and which materials and products carry each one, is posted in the production room and is in the Team Portal: the allergens of every material are on its FRM-207 entry (SQF 2.8.1.1 iv).", "The risk analysis", "• The SQF Practitioner assesses every raw material, ingredient and processing aid, and every lubricant that could touch product, for the allergens it contains or may contain. The record is the material's FRM-207 entry, taken from the manufacturer's label or specification (SQF 2.8.1.1 i).", "• What the analysis found:", "◦ Wheat, milk, egg and soy are in the cake base, the egg, the oil and the pan release spray. Every product made here - the rum cakes and the products packed for another customer - contains all four and declares all four, so between products they cannot make one unsafe for a person who can eat another. The risk there is the label, not cross-contact. A new product that does not declare one of the four makes that allergen a changeover for it, the same as a nut.", "◦ Tree nuts are in some products and not in others: pecans in some rum cakes, walnuts and almonds in products packed for another customer. This is the allergen that can cross from one product to another, on the mixer, the depositor, the pans, the racks, the dipping and packing tables, utensils, hands and clothing. It is the risk this program is built around.", "◦ Each tree nut is its own allergen on a label. A product with one nut made after a product with a different nut is a changeover, the same as a product with no nuts.", "◦ Processing aid: the pan release spray contains soy, which every cake already declares.", "◦ Lubricants: the food-grade grease and oil used on the depositor and the mixer are assessed from the manufacturer's allergen statement, kept with the material's FRM-207 entry.", "◦ A new material, a new brand of an existing material, or a new product is assessed before it is used (SOP-2.3.2, SOP-2.3.4).", "Allergens brought in by people", "• Staff food, drink and bags are kept and eaten only in the break area, which is separate from the production and storage rooms. Nothing is eaten or drunk in production (FSQM-012).", "• Hands are washed on entering the production room and after eating. Outer clothing worn in production is not worn in the break area while eating.", "• Visitors and contractors agree to the same rules on the entrance screen before they go in (FRM-906), and bring no food past reception.", "• There is no vending machine on site. Peanuts and peanut products are the allergen most likely to arrive in a lunch; the hand wash and the break area rule are the control (SQF 2.8.1.1 ii).", "Receiving and storing", "• At receipt the brand and product are checked against FRM-207 on FRM-301. A different brand is a new material: its allergen statement, including any \"may contain\", is checked before it is used (SOP-2.3.4).", "• Nuts are kept in closed, labelled containers on the allergen rack in the production room, below other materials and never above them. An opened pack is resealed or put in a lidded container labelled with the product and the word NUTS.", "• A scoop, bowl or container that has been used for nuts is washed with detergent, rinsed and sanitized before it is used for anything else. It is part of the changeover clean. Sanitizer alone does not remove an allergen; the wash and rinse do. A spill is cleaned up at once.", "• Segregation is checked on every day nuts are handled, on that day's FRM-903 (\"Allergen controls / segregation followed\"), and every month in the GMP inspection on FRM-913 (SQF 2.8.1.3).", "Making product - the changeover rule", "• Products without nuts are made first. Products with nuts are made last in the day, and the full clean follows them.", "• A changeover clean is done before any product that does not declare an allergen the product before it contained. On this site that means: after a product with a nut and before a product without that nut (SQF 2.8.1.6).", "• The changeover clean is the full clean in each machine's cleaning procedure - SOP-901 for the mixer, SOP-902 and SOP-903 for the depositors, SOP-904 for the kettle - and covers everything else the product touched: pans, racks, tables, scoops and utensils. It removes all visible residue from every product contact surface (SQF 2.8.1.4).", "• It is recorded on that machine's cleaning log - FRM-909, FRM-910, FRM-911 or FRM-912 - with \"Allergen changeover\" ticked and the line \"every food contact surface checked under good light\" completed.", "• Aprons and gloves are changed and hands washed after handling nuts and before handling a product without them.", "• Rework: a unit whose seal failed is re-pouched as the same product only, keeps the product name and lot code it had, and is counted on that lot's record (FRM-520). Product is never reworked into a different product, so a nut is never carried into a product that does not declare it (FSQM-019) (SQF 2.8.1.10).", "• Labels: the allergens on every label are approved on FRM-601 and the label applied is checked at release on FRM-701 (SOP-2.3.2.3). Every product made on the shared equipment is labelled with its allergens as United States law requires, and every pack also states that the nut is present or that the facility processes tree nuts. That statement does not replace the changeover clean (SQF 2.8.1.7).", "• These controls are carried into the food safety plan: the allergen hazards at each step are in FSQM-016 Part 7 (SQF 2.8.1.1 v, vi).", "Proving the clean works", "• Looking at a surface does not prove that an allergen is gone. The changeover clean is validated and verified with a test kit that detects the nut that was run, recorded on FRM-916 (SQF 2.8.1.5).", "• Validation: for each machine, the first three changeover cleans after a nut cake are swabbed after cleaning and before the next use. All three must show nothing detected.", "• Verification: every changeover clean is inspected under good light and recorded on the machine's cleaning log. In addition, one changeover clean on each machine is swabbed at least once a year.", "• How often to swab depends on the product made after the nut. Once a year is enough where its pack lists the nut or states that the facility processes tree nuts, because a person with a nut allergy is warned off it. Every product made here has such a pack today: the rum cake box lists pecans and states that the facility processes nuts, and the other customer's packs state \"manufactured in a facility that processes tree nuts, peanuts\". A new product whose pack has no such wording is swabbed at least every three months, and does not follow a nut product on a machine until that machine's validation has passed.", "• The clean is validated again when the cleaning method, the detergent, the equipment, or the nut changes.", "• If a swab detects the allergen: the surface is cleaned and swabbed again, nothing is made on it until it passes, any product made since the last passing check is held on FRM-702 under FSQM-018, and a CAPA is raised on FRM-007.", "If something goes wrong", "• A nut found in or on a product that does not declare it, a wrong label, or a clean that was missed: stop, hold the product on FRM-702, and tell the SQF Practitioner. If product has left the site, FSQM-023 starts.", "Instruction", "• All staff complete the allergen training modules in the Team Portal (TRN-003, TRN-004 and TRN-004A) when they start and as they come due. Whoever receives, stores or handles nuts is shown this program and the changeover rule on the floor. The Team Portal keeps the record (SQF 2.8.1.2).", "Review", "• The SQF Practitioner reviews this program at least once a year, and before a new allergen, material or product is brought in. The review is recorded as a revision of this document.", "Stated limitations at issue", "> THIS PROGRAM WAS ISSUED ON 2026-10-29 WITH THESE OPEN, by management's decision. Each names what closes it, who owns it and when. When one closes, this Part is revised.", "• THE TEST KIT. A kit that detects pecans, walnuts and almonds on a cleaned surface is chosen and bought by 2026-11-30. Owner: Senior Site Management.", "• VALIDATION. The first three changeover cleans on each machine after a nut product are swabbed and recorded on FRM-916 by 2027-01-31. Until then the changeover clean is checked by looking, as it has been. Owner: SQF Practitioner.", "• THE CLEANING LOGS. The mixer and depositor logs (FRM-909, FRM-910, FRM-911) have not yet been used. From the next nut product, every changeover clean is recorded on the machine's log with 'Allergen changeover' ticked. Owner: SQF Practitioner.", "• THE MATERIALS. Pecans, walnuts, almonds, the liquid egg and the lubricants are entered on FRM-207 with their allergen statements, and the allergen list is posted in the production room, by 2026-12-31. Owner: SQF Practitioner.", "• TRAINING. TRN-003, TRN-004 and TRN-004A are read against this program, and changed where they disagree with it, by 2026-12-31. Owner: SQF Practitioner.", "Records", "• FRM-207, FRM-301, FRM-903, FRM-913, the cleaning logs FRM-909 to FRM-912, FRM-916 and FRM-007 are kept as SOP-2.2.3 requires."], "definitions": "Allergen: one of the nine major food allergens listed in this program.\nCross-contact: an allergen getting into a product that does not contain it.\nChangeover: going from a product that contains an allergen to a product that does not declare it.\nChangeover clean: the full clean of everything the first product touched, done before the second product.\nValidation: proving once that the clean removes the allergen.\nVerification: checking, each time and at intervals, that the clean was done and still works.", "responsibility": "SQF Practitioner - carries out the risk analysis, keeps the allergen list and this program current, plans the swabs and decides what is done with a failed result. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nSenior Site Management - approves new materials, products and labels, and sets the production order.\nProduction staff - follow the production order, keep nuts apart, do and record the changeover clean, and report anything that goes wrong.\nAll staff - keep food in the break area and wash hands on entering production.", "form_references": "FRM-916 - Allergen Cleaning Verification Record\nFRM-909 - Mixer Cleaning & Pre-Use Check Log\nFRM-910 - Kook-E-King Depositor Cleaning & Pre-Use Check Log\nFRM-911 - Depositor Cleaning & Pre-Use Check Log (Beldos 275)\nFRM-912 - Kettle Cleaning & Pre-Use Check Log (Groen TDB)\nFRM-207 - Material Specification Register\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record\nFRM-913 - GMP / Food Safety Inspection Record\nFRM-601 - Label Review & Approval Form\nFRM-701 - Finished Product Release Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "revision_history": "New - 2026-10-05 - DRAFT under D-23, for the Minor findings against 2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.5 and 2.8.1.6. The site had no allergen management program.\n\nOWNER'S ANSWERS (2026-10-05): the allergens on site are wheat, milk, egg, soy, pecans and other tree nuts; cakes with nuts are made last in the day; the changeover clean is checked by looking only, with no swab; staff eat and keep their food in a separate break area. The finished pack declares wheat, milk, egg and soy on every cake.\n\nSOP-204 Allergen Cleaning Procedure (a three-line draft, never issued) is REPLACED by this program and is archived when this program is issued. Its ATP swab does not show that an allergen is gone, which was the finding against 2.8.1.5. The changeover clean was already written, machine by machine, in SOP-901 to SOP-904, and recorded on FRM-909 to FRM-912. So there is no separate Allergen Changeover Log, and the number clash on FRM-204 goes away: FRM-204 stays the supplier evaluation checklist.\n\n2.8.1.4 was scored Compliant against SOP-204, so this program takes it over.\n\nNEW REQUIREMENT, NOT YET DONE: swabbing with an allergen test kit (validation, then once a year).\n\nAT ISSUE: archive SOP-204; add a three-monthly 'allergen cleaning verification' row (the shorter of the two intervals) to the verification schedule (FSQM-017 Part 6) against FRM-916.\n\nTO CONFIRM BEFORE ISSUE: (1) for each product packed for another customer: which of wheat, milk, egg and soy it contains and declares, and whether its packaging carries a tree nut statement; (2) every material in use, including the nuts, the egg and the lubricants, entered on FRM-207 with its allergen statement; (3) the allergen list posted in the production room; (4) the nuts' place on the allergen rack; (5) a test kit chosen that detects the nuts used, and the three validation cleans per machine recorded on FRM-916; (6) that there is no vending machine; (7) the machine cleaning logs FRM-909 to FRM-912 in use on changeover days; (8) TRN-003, TRN-004 and TRN-004A read against this program.\n\nOWNER'S DECISION (2026-10-05): nuts do not have their own scoop. A utensil used for nuts is washed, rinsed and sanitized before any other use. SQF 2.8.1.4 asks for separate equipment only where a clean is not possible. The first draft's dedicated scoop went further than the clause.\n\nOWNER'S DECISION (2026-10-05): segregation is checked on the days nuts are handled and in the monthly inspection, not on every production day. Tree nuts are the only allergen that can cross between products here, so a day without nuts has nothing to keep apart beyond the closed containers on the rack. SQF 2.8.1.3 asks for continual monitoring; monthly alone was judged too little.\n\nOWNER'S DECISION (2026-10-05): every cake is packed in the same box, which lists pecans and carries the facility statement. On that basis the verification swab is once a year, not every three months, and the first draft's rule that no nut-free cake follows a nut cake until validation has passed is removed. The changeover clean itself stays: a label statement does not replace it (FDA guidance; SQF 2.8.1.4 and 2.8.1.6), and SQF 2.8.1.5 sets verification by risk assessment. The easing applies only to product packed with that wording.\n\nOWNER'S ANSWERS (2026-10-05): the only tree nuts on site besides pecans are walnuts and almonds, and they are in products packed in another customer's packaging, not in the rum cake box. The program now names the three nuts. The yearly swab, which rests on the rum cake box's wording, is limited to the rum cakes; a product whose pack has no such wording keeps the three-monthly swab and waits for the machine's validation. The earlier draft said every cake made here contains wheat, milk, egg and soy; that is stated of the rum cakes only until the other customer's products are checked.\n\nNew - 2026-10-29 - ISSUED, approved GJM, effective 2026-10-29, with the open items stated in a new Part 'Stated limitations at issue'. Management decided to issue before a test kit is chosen, reversing the decision of 2026-10-07 to wait for one. OWNER'S ANSWERS: the other customer's walnut and almond products contain the same four allergens plus the nut (2026-10-07), and their packs state \"manufactured in a facility that processes tree nuts, peanuts\" (2026-10-29); so every product made here declares the four and carries nut wording, and the yearly verification swab applies to all of them. Rework (2.8.1.10) and allergen labelling (2.8.1.7) are now cited on the lines that meet them; 2.8.1.11 is declared not applicable. Limitations: test kit by 2026-11-30; validation swabs by 2027-01-31; changeover cleans recorded on FRM-909 to FRM-911 from the next nut product; nuts, egg and lubricants on FRM-207 and the allergen list posted by 2026-12-31; TRN-003/004/004A read against the program by 2026-12-31. At issue: SOP-204 archived; the yearly allergen swab joined the verification schedule (FSQM-017 v21), first due 2027-01-31.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.4, 2.8.1.5, 2.8.1.6 (Allergen Management).\n\nSOP-901, SOP-902, SOP-903, SOP-904 - the cleaning procedure for each machine.\nSOP-2.3.2 specification control; SOP-2.3.4 Vendor Approval; SOP-2.3.2.3 Label Control.\nFSQM-012 Good Manufacturing Practices Program.\nFSQM-016 Food Safety Plan (HACCP) - Part 7, the hazard analysis.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-019 Rework; FSQM-009 CAPA Program; FSQM-023 Product Withdrawal and Recall Program.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here.", "not_applicable": [{"clause": "2.8.1.11", "reason": "The site handles allergenic materials and makes allergenic products. 2.8.1.11 is for sites that do neither; this program meets 2.8.1.1 to 2.8.1.10 instead."}]}$jx$::jsonb, sqf_reference = '2.8.1.1, 2.8.1.2, 2.8.1.3, 2.8.1.4, 2.8.1.5, 2.8.1.6, 2.8.1.7, 2.8.1.10',
       status = 'active', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FSQM-027' and status = 'draft';

update public.sop_documents set content = $jx${"form_schema": {"sections": [{"id": "check", "title": "1. The check", "fields": [{"id": "how_this_works", "text": "One record each time surfaces are swabbed for an allergen after a changeover clean (FSQM-027). Swab after the clean and before the equipment is used again. Validation is the first three changeover cleans on each machine; after that, as often as FSQM-027 sets for the product made next: once a year, or every three months. Follow the test kit's own instructions, and attach a photo of each result.", "type": "info", "label": "How to use this"}, {"id": "reason", "type": "select", "label": "Reason", "width": "third", "options": ["Validation", "Routine verification", "After a change to the clean, equipment or nut", "Re-test after a failed result"], "required": true, "showInList": true}, {"id": "date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true}, {"id": "product_before", "type": "text", "label": "Product made before the clean", "width": "third", "required": true, "showInList": true}, {"id": "allergen", "help": "The nut that was in the product, for example pecan", "type": "text", "label": "Allergen tested for", "width": "third", "required": true}, {"id": "kit", "help": "Maker and name", "type": "text", "label": "Test kit", "width": "third", "required": true}, {"id": "kit_lot", "type": "text", "label": "Kit lot and expiry", "width": "third", "required": true}, {"id": "cleaning_log", "help": "Which log and date - FRM-909, FRM-910, FRM-911 or FRM-912", "type": "text", "label": "Cleaning log for this clean", "width": "half"}]}, {"id": "swabs", "title": "2. Swabs", "fields": [{"id": "swabs", "rows": {"min": 1, "mode": "dynamic", "addLabel": "Add swab"}, "type": "grid", "label": "Surfaces swabbed", "columns": [{"id": "equipment", "type": "select", "label": "Equipment", "width": 1.5, "options": ["Mixer - bowl", "Mixer - paddle, whip or dough arm", "Kook-E-King depositor", "Beldos depositor", "Kettle", "Pans or molds", "Racks", "Table or work surface", "Scoop or utensil", "Other"], "required": true}, {"id": "surface", "type": "text", "label": "Where exactly", "width": 2, "required": true, "scanFact": "none"}, {"id": "result", "type": "select", "label": "Result", "width": 1, "options": ["Not detected", "DETECTED"], "required": true}, {"id": "notes", "type": "text", "label": "Notes", "width": 1.5, "scanFact": "none"}], "required": true, "rowDialog": true}]}, {"id": "outcome", "title": "3. Result and actions", "fields": [{"id": "overall", "type": "select", "label": "Overall", "width": "half", "options": ["Pass - nothing detected", "Fail - allergen detected"], "required": true, "showInList": true}, {"id": "actions", "help": "The re-clean and re-test, any product held on FRM-702, and what will change in the clean", "type": "textarea", "label": "If detected: what was done"}, {"id": "capa_no", "type": "text", "label": "CAPA Report no. (FRM-007)", "width": "third"}]}, {"id": "sign", "title": "4. Sign-off", "fields": [{"id": "completed_by", "role": "filler", "type": "signature", "label": "Swabbed by", "required": true, "statement": "The swabs were taken after the clean and before the equipment was used again, and the results are as shown."}, {"id": "reviewed_by", "role": "verifier", "type": "signature", "label": "Reviewed by the SQF Practitioner", "required": true, "statement": "I have reviewed this record and the actions taken."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{reason} - {date}"}, "schemaVersion": 1}, "revision_history": "New - 2026-10-29 - Issued with FSQM-027. Approved GJM, effective 2026-10-29."}$jx$::jsonb,
       status = 'active', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FRM-916' and status = 'draft';

update public.sop_documents set status = 'archived' where sop_number = 'SOP-204' and status = 'draft';

update public.sop_documents set content = $jx${"scope": "The rum cake, all flavours, from the receipt of ingredients and packaging to dispatch to the customer's carrier, across the three-day production rotation. Other products made on the site are not covered by this plan.", "purpose": "This is the food safety plan for the rum cake. It states, to the twelve steps of the Codex Alimentarius HACCP guidelines, how Adventure Bakery identifies the hazards in making it, decides which are significant, and controls them, and how that control is monitored, corrected and verified.", "records": "• Attachment A, with its confirmation block dated and signed\n• FRM-507 and FRM-606 CCP monitoring records, with their weekly review signatures\n• FRM-702 holds and FRM-007 corrective actions arising from a CCP deviation\n• Food safety team review records - the revisions of this plan, and the annual review on FRM-001\nSuperseded revisions of this plan are retained by the sop_document_history trigger.", "procedure": ["Scope", "> The plan starts at the receipt of ingredients and packaging and ends when finished product is collected by the customer's carrier. Every input and output in between - raw materials, packaging, service inputs, the two overnight delays, waste and rework - is shown on the flow diagram in Attachment A (SQF 2.4.3.3).", "> COUNTRY OF PRODUCTION AND DESTINATION (SQF 2.4.3.17). The product is made in the United States and is sold today only in the United States. This plan follows the Codex HACCP guidelines. United States law prescribes its own method, the FDA's Preventive Controls for Human Food rule (21 CFR 117, Subpart C). The site is a qualified facility under that rule - a very small business, with less than $1 million a year in sales of human food, averaged over the previous three years (21 CFR 117.3) - so Subpart C does not apply to it and the modified requirements of 21 CFR 117.201 do. This plan, with the current good manufacturing practices of 21 CFR 117 Subpart B that the site's programs carry, is how the site meets both.", "• THE MODIFIED REQUIREMENTS. Senior Site Management submits the qualified facility attestation to the FDA (Form FDA 3942a), attesting that the site has identified the hazards in its food and implements and monitors preventive controls - this plan is the basis for it. It is submitted every two years, with the facility registration renewal between 1 October and 31 December of each even-numbered year, and the yearly sales figures that support the status are kept. Because the attestation is to these food safety practices and not to compliance with state or local law, the consumer notice of 21 CFR 117.201(e) - this facility's own name and address on the label - does not apply. The label names the manufacturer, packer or distributor as 21 CFR 101.5 requires (\"Manufactured by\", \"Manufactured for\" or \"Distributed by\"), which is checked when the label is approved on FRM-601.", "• IF THE STATUS CHANGES. If sales reach $1 million a year, averaged over three years, the site is no longer a qualified facility and must meet Subpart C in full, including a Preventive Controls Qualified Individual. Senior Site Management checks the figure each year at the management review (FRM-001), and this plan is revised before the status is lost.", "• A NEW DESTINATION. Before the first shipment to any other country - the United Kingdom is the one planned - the food safety team identifies that country's food safety requirements, records here how this plan meets them, and revises this plan.", "Product description", "• Product: rum cake, in several flavours, made for Bahamas Rum Cake Factory. A shelf-stable baked product, stored and distributed at ambient temperature.", "• Composition: cake mix (containing wheat flour, sugar and nonfat dry milk), liquid whole eggs, soybean oil, water and flavour emulsion; the molds are sprayed with a pan release of soybean oil and soy lecithin before depositing; after baking, dipped in a syrup of water, sugar and rum.", "• Allergens: wheat, milk, egg and soy, as declared on each flavour's approved label.", "• Packaging: vacuum-sealed pouch in a baking cup, in an individual product box; boxes packed in coded master cases, palletized and stretch wrapped.", "• Shelf life: 12 months, printed on the pack as a Best By month and year.", "• Water activity and pH: not yet measured.", "> Each flavour's finished product specification is its entry on FRM-704, which this description refers to (SQF 2.4.3.4). The product is called shelf stable because of reduced water activity, but that figure has not been measured, and the syrup added after baking returns water and sugar to the product. Part 7 has therefore been written with growth in the sealed product scored as significant. The water activity of the finished, sealed product is recorded here when it has been measured, and that line of Part 7 is then scored again.", "Intended use", "• Ready to eat; no further cooking by the consumer.", "• General public. The product contains rum. The caution carried from the June 2026 plan stands: not for immunocompromised individuals, infants or pregnant women without a physician's guidance (SQF 2.4.3.5). The food safety team confirms the caution and the groups it names at its first review after HACCP training (Part 9).", "Food safety team", "• SQF Practitioner - leads the team. Brings the production process, the equipment and the CCP monitoring as they are performed on the floor.", "• Senior Site Manager - substitute SQF Practitioner. Brings the product, its formulation, raw materials and packaging, and approves this plan.", "• Engineering knowledge is not held on the team. It is taken from the equipment manufacturers' manuals and their service technicians, and the source is named wherever this plan relies on it (SQF 2.4.3.2).", "• Who holds each position is recorded on FRM-005 and in FSQM-004, not here, so that this plan does not have to be reissued when a person changes.", "• The team meets at least annually for the full review and whenever a change requires one (Part 10). Its decisions are recorded by revising this plan, and the annual review is also recorded on FRM-001.", "> HACCP TRAINING - NOT YET HELD. No member of the team holds a HACCP training certificate. SQF 2.1.1.5 requires the SQF Practitioner to have completed HACCP training, and 2.4.3.2 asks for a team with the competence to develop the plan. The SQF Practitioner and the Senior Site Manager are each to complete a HACCP course by the dates in Part 9; each certificate is filed on FRM-952 and this Part revised to say so. Until then the team meets 2.4.3.2 in its membership but not yet in its training, and this plan is issued as a limited plan on that basis.", "Process flow diagram", "• The flow diagram is Attachment A. It shows every step from receipt to dispatch across the three days, every raw material, packaging item and service input, the two scheduled overnight delays, and every output including waste and the one rework loop.", "• The food safety team confirmed it by walking the floor on all three days of the rotation, so that every step was seen as it is performed, and corrected it on 2026-09-28. The confirmation block on the diagram is dated and signed once, and the signed sheet is attached to this plan (Part 9). That signed block is the confirmation SQF 2.4.3.6 requires. It is not signed daily.", "• The diagram is re-confirmed whenever the process, equipment or rotation changes, and at the annual review of this plan.", "> FSQM-039 Facility Layout and Product Flow shows where equipment stands and where product goes on the floor. It is not this flow diagram and is not offered as one.", "Hazard significance methodology", "• Name every hazard specifically and type it as biological, chemical (allergens included) or physical: Salmonella, not \"pathogens\"; hard or sharp foreign material from a named source, not \"foreign material\".", "• LIKELIHOOD, judged as if the step's own control measure were absent:", "◦ 1 = Unlikely: no record of it for this material or process, in the industry or at the site.", "◦ 2 = Possible: known to occur in the industry for this kind of material or process.", "◦ 3 = Likely: has occurred at this site, or is expected without control.", "• SEVERITY, the worst harm a consumer could reasonably suffer:", "◦ 1 = Low: brief discomfort, no lasting effect.", "◦ 2 = Moderate: illness or injury needing treatment, without lasting harm.", "◦ 3 = High: serious illness or injury, hospitalisation or death.", "• ALWAYS SEVERITY 3: an undeclared allergen; a pathogen such as Salmonella or Listeria monocytogenes; hard or sharp foreign material 7 mm to 25 mm long.", "• SCORE = likelihood × severity. 6 or 9 = SIGNIFICANT. 1 to 4 = not significant, and the analysis records why.", "• EVIDENCE FOR \"UNLIKELY\": a severity 3 hazard scored as unlikely (a score of 3) records the evidence that makes it unlikely. \"Unlikely\" cannot be asserted without it.", "> WHY THE STEP'S OWN CONTROL IS SET ASIDE. A hazard is judged as if the control at that step were not there. Otherwise every hazard the site already controls would score as unlikely and not significant, and the analysis would conclude that nothing needs controlling. A prerequisite program that is documented, implemented and verified - supplier approval, GMP, sanitation, pest control - may be counted when judging likelihood, and the analysis names the program it relies on.", "> Evidence for a likelihood or severity score comes from the FDA's Hazard Analysis and Risk-Based Preventive Controls for Human Food guidance (its appendix of hazards by ingredient and process), product recalls and outbreaks involving similar products, supplier information, and this site's own records of complaints, holds and deviations.", "• Every significant hazard is given a control measure in Part 7 and is taken through the CCP decision in Part 8. Every hazard that is not significant is recorded with the reason and the prerequisite program that keeps it so.", "• Each row of the analysis records the step, the hazard, its type and source, the likelihood, severity and score, whether it is significant, the justification, and the control measure.", "> This method is applied in exactly the same way to every hazard at every step (SQF 2.4.3.8). It is changed only by revising this Part, and a change to it means every hazard in Part 7 is scored again.", "Hazard analysis and control measures", "> This Part applies the method in Part 6 to every step on Attachment A. Each line under a step is one hazard: its type (B biological, C chemical including allergens, P physical), what it is and where it comes from, likelihood × severity = score, whether it is significant, why, and the control measure. Likelihood is judged as if the step's own control were absent (SQF 2.4.3.7 to 2.4.3.9).", "> THE SCORES BELOW WERE ADOPTED BY THE FOOD SAFETY TEAM WHEN THIS PLAN WAS ISSUED. Because no member of the team yet holds HACCP training, the trained team reviews every line again, against the floor, within 30 days of the first certificate (Part 9).", "• STEP 1 - Receive ingredients and packaging.", "◦ B - Salmonella and Shiga toxin-producing E. coli in the cake mix (wheat flour, nonfat dry milk): L2 × S3 = 6, SIGNIFICANT. Flour is milled from raw grain and is not treated to kill pathogens; flour and dry mixes have caused outbreaks and recalls, and milk powder is a known Salmonella vehicle. Control: the bake at step 7.", "◦ B - Salmonella in the liquid whole egg: L2 × S3 = 6, SIGNIFICANT. Liquid egg is normally sold pasteurised, but Salmonella survives a failed pasteurisation and grows if the cold chain fails. Control: supplier approval (SOP-2.3.4, FRM-202), receipt at 41°F or below recorded on FRM-301 (FSQM-035), and the bake at step 7.", "◦ C - An allergen that is not on the finished product's label, arriving in an ingredient: a supplier changes a recipe, or a different brand is bought in place of the usual one. L2 × S3 = 6, SIGNIFICANT. The ingredients are bought from cash-and-carry suppliers, where the brand on the shelf can change. Control: each material's declaration is recorded word for word from its pack on FRM-207, and the brand received is recorded on FRM-301.", "◦ C - Mycotoxins and pesticide residues in the wheat flour and sugar: L1 × S2 = 2, not significant. Regulated at the mill and the refinery; no history at the site. Kept so by supplier approval (SOP-2.3.4).", "◦ P - Hard or sharp foreign material (metal, glass, stone, hard plastic) in an ingredient as received: L2 × S3 = 6, SIGNIFICANT. It is known to occur in bagged dry ingredients, and the site holds no supplier evidence that would make it unlikely. Control: NONE AT THIS SITE TODAY - there is no sieve, magnet or metal detector (FSQM-013). See the findings below.", "◦ C - Food-contact packaging (vacuum pouches, baking cups) that is not suitable for food: L1 × S2 = 2, not significant. Kept so by the packaging specifications on FRM-207; the suppliers' letters of guarantee are still to be obtained.", "• STEP 2 - Store: dry goods at ambient temperature, liquid eggs refrigerated.", "◦ B - Salmonella growing in liquid egg held above 41°F: L2 × S3 = 6, SIGNIFICANT. Control: the walk-in is monitored continuously, with alerts (SOP-401, FRM-401); the bake at step 7.", "◦ C - An allergen that is not on this product's label, from another product's ingredients stored on site: L2 × S3 = 6, SIGNIFICANT. Control: allergen ingredients are kept sealed on their own labelled rack and never above other ingredients (FSQM-035).", "◦ C - Cleaning chemicals contaminating stored ingredients or packaging: L1 × S2 = 2, not significant. Chemicals are kept in the locked locker, away from ingredients and packaging (FSQM-032, FSQM-035).", "◦ B, P - Contamination by pests: L2 × S2 = 4, not significant. Kept so by FSQM-031 and by sealed containers.", "• STEP 3 - Weigh and measure ingredients, including water.", "◦ B - Pathogens from hands, utensils or the bench into the ingredients: L2 × S3 = 6, SIGNIFICANT. Control: the bake at step 7; handwashing and illness rules (FSQM-012); the pre-operation check (FRM-903).", "◦ B, C - Contaminated water used as an ingredient: L1 × S3 = 3, not significant. Evidence: the City of Sanford's treated supply and its annual water quality report (FRM-915), and the water is then baked. FSQM-033 is still a draft and the site's own yearly test has not yet been done.", "◦ P - Pieces of ingredient packaging (paper, film, thread) falling in when a bag is opened: L2 × S2 = 4, not significant. Soft, not hard or sharp. Kept so by GMP (FSQM-012).", "• STEP 4 - Mix batter.", "◦ P - Metal from the mixer bowl, the agitator or a loose part: L2 × S3 = 6, SIGNIFICANT. Control: the mixer is checked clean, complete and with nothing left on it before use (FRM-909) and is on the monthly maintenance check (FSQM-029, FRM-508). There is no detection step after it - see the findings below.", "◦ C - An allergen that is not on this product's label, left on the mixer by a different product: L2 × S3 = 6, SIGNIFICANT. Control: the allergen changeover clean and inspection (SOP-901), recorded on FRM-909.", "◦ C - Detergent, sanitizer or lubricant left on the mixer: L1 × S2 = 2, not significant. The sanitizer is made up to its no-rinse food-contact strength and read with a test strip (SOP-901, FSQM-032).", "◦ B - Staphylococcus aureus growing and forming toxin in batter left standing: L1 × S2 = 2, not significant. All batter is deposited and baked on the day it is mixed.", "• STEP 5 - Spray molds with pan release.", "◦ C - Soy, from the soy lecithin in the pan spray: present by design and declared on the label, so it is not scored here. A change of pan spray is the ingredient hazard at step 1.", "◦ P - Fragments from a chipped, cracked or flaking mold: L1 × S3 = 3, not significant. Evidence: every mold is checked before each use and inspected at each wash, and a damaged mold is taken out of service (SOP-906, FRM-903).", "• STEP 6 - Deposit batter into the sprayed molds.", "◦ P - Metal, hard plastic, a seal or an O-ring from the depositor: L2 × S3 = 6, SIGNIFICANT. Control: the depositor is checked at reassembly and before use (FRM-910, FRM-911) and is on the monthly maintenance check (FSQM-029). There is no detection step after it - see the findings below.", "◦ C - An allergen left on the depositor by a different product: as for the mixer at step 4, SIGNIFICANT. Control: the allergen changeover clean (SOP-902, SOP-903), recorded on FRM-910 or FRM-911.", "• STEP 7 - Bake.", "◦ B - Salmonella, Shiga toxin-producing E. coli and Listeria monocytogenes from the flour, egg and milk powder surviving the bake: L3 × S3 = 9, SIGNIFICANT. They are expected in raw batter and this is the only step that kills them. Control: oven at 350°F or above for at least 27 minutes, recorded for every load on FRM-507. These limits are carried from the June 2026 plan and have not been validated for this product in this oven, and the product's internal temperature is not measured - see the findings below.", "◦ B - Spores of Bacillus cereus and Clostridium species from the flour, sugar and milk powder surviving the bake: L3 × S2 = 6, SIGNIFICANT. Baking does not kill spores; they are a hazard only if they can grow afterwards. Control: none at this step. Growth is prevented by the water activity of the finished product, which has not been measured - see step 13.", "◦ C - Acrylamide formed in baking: L2 × S1 = 2, not significant. A long-term dietary concern, not an acute one, at a normal bake colour.", "• STEP 8 - Remove from the oven and cool in the pans, covered, at room temperature.", "◦ B - Salmonella or Listeria monocytogenes reaching the baked product from racks, covers, hands or the room: L2 × S3 = 6, SIGNIFICANT. The product is ready to eat from here on, and nothing later kills what lands on it. Control: sanitation and the pre-operation release (FRM-903, FRM-902), GMP (FSQM-012) and the hygiene zoning of the cooling area (FSQM-039). Environmental monitoring (FSQM-015) verifies it; its first round is due by 2027-01-31.", "◦ B - Spores that survived the bake growing while the product cools: L2 × S2 = 4, not significant, PROVISIONAL. The cooling time is not limited - depanning may follow later the same day or the next day - and whether spores can grow in the baked product depends on its water activity, which has not been measured.", "• STEP 9 - Depan.", "◦ B - Staphylococcus aureus, norovirus or Salmonella from hands onto ready-to-eat product: L2 × S3 = 6, SIGNIFICANT. Control: handwashing, gloves and the illness and wound rules (FSQM-012), checked on the GMP inspection (FRM-913).", "• STEP 10 - Prepare dipping syrup, only when none is in stock.", "◦ B - Pathogens in the sugar, water or rum: L1 × S3 = 3, not significant. Evidence: refined sugar, treated city water and distilled spirit are not known vehicles for Salmonella, and the sugar and water are heated in the kettle before the rum is added. The temperature reached is not recorded.", "◦ B - Yeasts, molds or bacteria growing in syrup kept for a later run: L2 × S2 = 4, not significant. The syrup is two parts sugar to one part water; the rum is added in the dunk tank and is not in syrup kept for a later run (corrected 2026-10-14 - this score was first written for a syrup with alcohol in it, and is for the food safety team to confirm). A concentrated sugar syrup, in which food-poisoning bacteria are not expected to grow. Its own water activity has not been measured. Kept so by the hold rule below.", "◦ SYRUP HOLD RULE. Prepared syrup is kept sealed, at room temperature, for no more than 30 days from the day it was made; it is normally used within a few days. The container is labelled with the date made and a lot code in the same form as the product's - the last digit of the year and the three-digit day of the year. Syrup that is past 30 days, unlabelled, or showing gas, cloudiness, mold or an off smell is discarded. Each batch made is recorded on FRM-530, with the supplier lots of the sugar used.", "◦ P - Fragments from the kettle or utensils: L1 × S3 = 3, not significant. Evidence: the kettle is cleaned and checked before use (SOP-904, FRM-912).", "• STEP 11 - Dip the baked product in syrup at room temperature. The rum is added to the syrup in the dunk tank. The lots of the syrup and the rum are written on the lot record (FRM-520).", "◦ B - Pathogens carried onto ready-to-eat product by the syrup, the dip container, utensils or hands: L2 × S3 = 6, SIGNIFICANT. This is a wet step after the only kill step. Control: the changeover clean of the dunk bay before Day 2 and its pre-operation release (FRM-903); GMP (FSQM-012); the syrup hold rule at step 10.", "◦ B - The syrup adds water back to the baked product. Its effect on growth in the finished product is scored at step 13.", "• STEP 12 - Place in baking cups.", "◦ B - Hand contact with ready-to-eat product: as step 9, SIGNIFICANT, with the same control.", "• STEP 13 - Vacuum seal.", "◦ B - Clostridium botulinum or Staphylococcus aureus growing in the sealed product during up to twelve months at room temperature: L2 × S3 = 6, SIGNIFICANT UNTIL THE WATER ACTIVITY IS MEASURED. A vacuum pouch removes air, which favours C. botulinum, and the product is kept unrefrigerated. Below a water activity of 0.85 no food-poisoning bacteria grow, and the product is believed to be below it; but Part 6 does not allow a severity 3 hazard to be called unlikely without evidence, and there is none. Control: the product's formulation - its sugar and rum - which becomes a stated control with a limit once the water activity of the finished, sealed product has been measured.", "◦ B - Contamination or mold growth through a leaking, channelled or partial seal: L2 × S2 = 4, not significant by this method. Every pouch is looked at as it comes off the sealer, for a leak, channel, wrinkle or partial seal and for air in the pouch, and is looked at again at boxing. Recorded on FRM-606.", "◦ REWORK - a pouch that fails is opened and the product re-pouched. The hand-contact hazard of step 9 applies, with the same control.", "• STEPS 14 TO 17 - Box; label, lot code and best-by date; pack and code master cases; palletize and stretch wrap.", "◦ C - The wrong label or box, or a label that does not declare wheat, milk, egg and soy: L2 × S3 = 6, SIGNIFICANT. Control: labels are approved on FRM-601 (SOP-2.3.2.3), and the label applied is checked against the approved label at release on FRM-701 (FSQM-020).", "◦ CCP 2 CHECK AT BOXING - before a pouch goes in its box it is looked at again, and a pouch that has lost its vacuum is rejected. One cooled pouch from each lot is pull tested before boxing starts. The pull test is not done at sealing: the film is still warm then, and a good seal can be pulled open. Recorded on FRM-606.", "◦ C - Coder ink: L1 × S1 = 1, not significant. It is applied to the outside of the box and the case only, never to a food-contact surface.", "• STEP 18 - Release check.", "◦ No hazard is introduced. The check on FRM-701 is itself a control: no batch leaves under an open hold, without its pre-operation release recorded, or with a label that is not the approved one (FSQM-020).", "• STEPS 19 AND 20 - Warehouse storage at ambient temperature, and dispatch.", "◦ B - Growth in the sealed product over its shelf life: scored at step 13.", "◦ B, P - Pests or handling damaging packs: L1 × S2 = 2, not significant. Kept so by FSQM-031, FSQM-035 and the loading check on FRM-801 (FSQM-036).", "• AT EVERY STEP.", "◦ P - Glass or brittle plastic from lights, gauges or fittings: L1 × S3 = 3, not significant. Evidence: every item is on the register and checked (SOP-11.7.3, FRM-907), and a breakage is handled on FRM-908.", "◦ P - Jewellery, pens, dressings and other personal items: L1 × S2 = 2, not significant. Kept so by FSQM-012.", "◦ C - Sanitizer or detergent on a food-contact surface at the wrong strength: L2 × S2 = 4, not significant. The strength is read with a test strip and recorded (FRM-903, FSQM-032).", "◦ Compressed air, ice and steam do not contact the product (FSQM-013), so no hazard arises from them.", "> WHAT THIS ANALYSIS FINDS. Four of the significant hazards above do not yet have a control that is in place and proven. This plan is issued with each of them stated as a limitation, with the action and date that closes it, in Part 9.", "• WATER ACTIVITY. Whether pathogens can grow in the finished product is not known, because its water activity has never been measured. The measurement that decides it is of the product as sold - after the dip, sealed, and left a day or more to settle - and not of the cake before it is dipped: the syrup puts water back, and the sealed pack is what sits at room temperature for a year. Water activity is not wetness; sugar and alcohol hold water so that microbes cannot use it, which is why a syrup-soaked cake can still measure low.", "• FOREIGN MATERIAL. Hard or sharp foreign material is a significant hazard at steps 1, 4 and 6, and nothing in the process would find it. The metal detector named in FSQM-013 Part 5 is the planned control; until it is installed and its limits are set, the pre-use equipment checks are the only measure.", "• THE BAKE. The limits of 350°F and 27 minutes have not been validated against this product in this oven, and the internal temperature is not measured. Validation is workbook tasks 14.7 to 14.9.", "• AFTER THE BAKE. Recontamination of ready-to-eat product at steps 8 to 12 is controlled by cleaning and hygiene alone. Environmental monitoring (FSQM-015) is what shows that this control works; it is issued, and its first round is due by 2027-01-31.", "> Part 8 takes each significant hazard through the CCP decision. Two results of this analysis bear on it. The failed-seal hazard at step 13 scores as not significant, so the team must decide whether vacuum sealing remains a critical control point. And if water activity proves to be the control for growth, its limit belongs in Part 8.", "Critical control points", "> Every significant hazard in Part 7 is taken through the four questions of the Codex decision tree, in the same way each time (SQF 2.4.3.10). The decisions below were adopted by the food safety team when this plan was issued, and are reviewed again by the trained team, as Part 7 is.", "• THE FOUR QUESTIONS, asked of each significant hazard at the step where it arises:", "◦ Question 1 - Do the prerequisite programs control it at this step? If yes, it is not a CCP. A program counts only when it is issued, in use and verified (Part 6).", "◦ Question 2 - Is there a control measure for it at this step? If there is none and control is needed for safety, the step, the process or the product has to change.", "◦ Question 3 - Will a later step remove it or bring it down to a safe level? If yes, that later step is where it is controlled.", "◦ Question 4 - Does this step remove it or bring it down to a safe level? If yes, this step is a CCP.", "• THE DECISIONS:", "◦ Pathogens in the cake mix and the liquid egg, their growth in egg held too warm, and pathogens from hands into the ingredients (steps 1, 2 and 3): Question 1 no - supplier approval, cold storage and GMP lower them but do not remove them. Question 3 yes - the bake. NOT A CCP at these steps; controlled at CCP 1.", "◦ Pathogens surviving the bake (step 7): Question 1 no. Question 2 yes. Question 3 no - nothing after the oven kills. Question 4 yes. CCP 1.", "◦ Spores surviving the bake (step 7), and Clostridium botulinum or Staphylococcus aureus growing in the sealed product (step 13): baking does not kill spores, so the only control is that the finished product cannot support growth. Question 2 cannot be answered until the water activity of the finished, sealed product is measured. NOT YET DECIDED. If it is 0.85 or below, the recipe and the dip that give that figure become a control with a limit, written here. If it is above, the product or the process has to change.", "◦ An undeclared allergen arriving in an ingredient, or from another product's ingredients in storage (steps 1 and 2): Question 1 yes - the material declarations on FRM-207, the brand check at receipt on FRM-301 and segregated storage (FSQM-027, FSQM-035). NOT A CCP.", "◦ An allergen left on the mixer or a depositor by a different product (steps 4 and 6): Question 1 yes - the changeover clean, checked and swabbed (FSQM-027, SOP-901 to SOP-903, FRM-916). NOT A CCP.", "◦ Hard or sharp foreign material in an ingredient, or metal from the mixer or a depositor (steps 1, 4 and 6): Question 1 no - the checks before use lower it but would not find it. Question 2 no - there is no control measure. THE PROCESS HAS TO CHANGE. Management's decision, 2026-10-07: a metal detector, not yet bought. When it is installed it becomes a CCP, with its limits and test pieces set when it is commissioned. A metal detector finds metal only: the team decides, with evidence from the suppliers, whether stone, glass and hard plastic in the dry ingredients are unlikely, or whether those ingredients are also sieved.", "◦ Recontamination of the baked product from surfaces, the room, the syrup or hands (steps 8, 9, 11 and 12): Question 1 yes - cleaning and the pre-operation release (FRM-903), GMP (FSQM-012) and the zoning (FSQM-039), with environmental monitoring (FSQM-015) to show they work. NOT A CCP: there is no later kill step, and nothing at these steps can be measured against a limit for each batch.", "◦ The wrong label, or a label that does not declare the allergens (steps 14 to 17): Question 1 yes - label approval on FRM-601 and the label check at release on FRM-701 (FSQM-020). NOT A CCP.", "• THE CRITICAL CONTROL POINTS:", "◦ CCP 1 - Baking (step 7): oven at least 350°F for at least 27 minutes, recorded on FRM-507 CCP 1 Baking Monitoring Record. The June 2026 plan also sets an internal temperature of at least 180°F at the end of the bake; the product is not probed today, and FRM-507 records that.", "◦ CCP 2 - Vacuum sealing (step 13): every pouch sealed intact with no leak, channel, wrinkle or partial seal and no air in the pouch. Every pouch is looked at as it comes off the sealer and again at boxing, where one cooled pouch from each lot is pull tested. Recorded on FRM-606 CCP 2 Vacuum Sealing Monitoring Record. The vacuum level and seal width for the site's machine are not yet confirmed.", "• CCP 2 IS KEPT, ALTHOUGH THE METHOD DOES NOT REQUIRE IT. A failed seal scores as not significant in Part 7, so the questions above would not make sealing a CCP. Management's decision, 2026-10-07: it stays a CCP, monitored and recorded as now, until the water activity is known and the team has HACCP training. It is decided again then.", "• CCP 1 is checked and recorded for every oven load. For CCP 2 every pouch is looked at, and a row is recorded at the first sealing, after any adjustment, at the end of the run and at boxing (SQF 2.4.3.12).", "• A failed limit stops the step. The affected product is held on FRM-702 and dispositioned under FSQM-018, and the cause is corrected under FSQM-009 on FRM-007 (SQF 2.4.3.13).", "• NOT YET IN PLACE. This plan is issued with the following open, each stated as a limitation in Part 9 with the action and date that closes it:", "◦ The critical limits of CCP 1 are not validated for this product in this oven (SQF 2.4.3.11).", "◦ The water activity is not measured, so growth in the sealed product has no decided control.", "◦ There is no metal detector.", "◦ FSQM-027 and FSQM-015 are issued, but the allergen validation swabs and the first environmental round are not yet done. The decisions above that rest on them hold once each is in use.", "◦ No member of the team holds HACCP training (Part 4), so these decisions have not yet been made by a trained team.", "Stated limitations at issue", "> THIS PLAN IS ISSUED AS A LIMITED PLAN. On 2026-10-29 management decided to issue it rather than wait, so that the rum cake is made under a controlled food safety plan that says plainly what is not yet proven, in place of the June 2026 plan, which did not. Each limitation below names the action that closes it, who owns it and the date it is due. When one closes, this Part and the Part it affects are revised, and the limitation is removed.", "• HACCP TRAINING (Part 4; SQF 2.1.1.5, 2.4.3.2). No member of the team holds a certificate. Action: the SQF Practitioner completes a HACCP course by 2027-01-31, the Senior Site Manager by 2027-03-31, each certificate filed on FRM-952. Owner: Senior Site Management.", "• TEAM REVIEW BY A TRAINED TEAM (Parts 7 and 8). The hazard analysis and the CCP decisions were adopted by a team not yet trained. Action: within 30 days of the first HACCP certificate, the team reviews every line of Parts 7 and 8 against the floor, confirms the intended-use caution in Part 3, and revises this plan. Owner: SQF Practitioner.", "• WATER ACTIVITY AND pH (Parts 2, 7 and 8; SQF 2.4.3.4). Not measured, so growth in the sealed product (step 13) has no decided control and CCP 2 is kept by management's decision. Action: finished, sealed product - after the dip, left a day or more to settle - sent to a laboratory for water activity and pH by 2026-11-30; the result recorded in Part 2, step 13 scored again, and the decision in Part 8 made. Owner: SQF Practitioner.", "• VALIDATION OF THE BAKE (Part 8, CCP 1; SQF 2.4.3.11, 2.5.1.1). The limits of 350°F for 27 minutes are carried from the June 2026 plan and the internal temperature of the product is not measured. Action: the bake validated for this product in this oven, including probing the internal temperature at the end of the bake, by 2027-02-28. Until then CCP 1 is monitored against the limits as stated. Owner: SQF Practitioner.", "• CCP 2 SPECIFICATION (Part 8; SQF 2.4.3.11). The vacuum level and seal width for the site's sealer are not confirmed. Action: obtained from the manufacturer and written into Part 8 and FRM-606 by 2026-12-31. Owner: SQF Practitioner.", "• FOREIGN MATERIAL (Parts 7 and 8). Hard or sharp foreign material has no control that would find it. Action: management's decision of 2026-10-07 is a metal detector; it is bought and installed by 2027-03-31, and on commissioning becomes a CCP with its limits and test pieces written into Part 8. The team decides, with supplier evidence, whether stone, glass and hard plastic in the dry ingredients are unlikely or the ingredients are also sieved. Until then the checks before use (FRM-909, FRM-910, FRM-911) are the only measure. Owner: Senior Site Management.", "• PROGRAMS THIS PLAN RELIES ON THAT ARE NOT YET FULLY IN USE (Part 8). Allergen management (FSQM-027) was issued on 2026-10-29; its test kit is chosen by 2026-11-30 and its validation swabs done by 2027-01-31. Environmental monitoring (FSQM-015) was issued on 2026-10-29; its laboratory is chosen by 2026-11-30 and its first round taken by 2027-01-31. The decisions that rest on them hold once each is in use; each document carries its own open items. Owner: SQF Practitioner.", "• THE SIGNED FLOW DIAGRAM CONFIRMATION (Part 5; SQF 2.4.3.6). The confirmation sheet signed on the floor is attached to this plan by 2026-11-30. Owner: SQF Practitioner.", "• 21 CFR 117 ATTESTATION (Part 1). The qualified facility attestation, to the site's food safety practices, is confirmed as submitted with the 2026 facility registration renewal by 2026-12-31. Owner: Senior Site Management.", "> These limitations are reviewed at each monthly SQF update (FRM-009) until all are closed.", "Verification and review", "• The CCP records are reviewed and signed weekly under FSQM-017 (SQF 2.4.3.15 and 2.4.3.16).", "• The food safety team reviews this plan in full at least annually, and whenever the product, ingredients, process, equipment or packaging changes in a way that could affect food safety (SQF 2.4.3.14 and 2.3.1.3)."], "attachments": [{"name": "FSQM-016 Att A - HACCP Process Flow Diagram - Rum Cake.pdf", "path": "f0ad5f61-a2b2-4e07-a363-9da74f96133f/files/FSQM-016_Att_A_-_HACCP_Process_Flow_Diagram_-_Rum_Cake.pdf"}, {"name": "FSQM-016 Att A - HACCP Process Flow Diagram - Rum Cake.drawio", "path": "f0ad5f61-a2b2-4e07-a363-9da74f96133f/files/FSQM-016_Att_A_-_HACCP_Process_Flow_Diagram_-_Rum_Cake.drawio"}], "definitions": "Critical control point (CCP): a step at which control is applied and is essential to prevent or eliminate a food safety hazard or reduce it to an acceptable level.\nCritical limit: the value that separates safe from unsafe product at a CCP.\nFood safety team: the people named in Part 4 who develop, maintain and review this plan.\nAttachment A: the process flow diagram, held with this plan as an editable master and a PDF.", "responsibility": "SQF Practitioner - leads the food safety team, maintains this plan, and reviews the CCP records.\nFood safety team - develops and reviews this plan, confirms the flow diagram on the floor, and conducts the hazard analysis.\nManagement team - approves this plan and provides what it requires.\nProduction staff - monitor the CCPs and record them on FRM-507 and FRM-606, and stop and hold product when a limit is not met.", "form_references": "FRM-507 - CCP 1 Baking Monitoring Record\nFRM-606 - CCP 2 Vacuum Sealing Monitoring Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective and Preventive Action record (FSQM-009)\nFRM-704 - Finished Product Specification\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-701 - Finished Product Release Record", "revision_history": "New - 2026-09-21 - DRAFT, under D-14. Created so the rebuilt plan has a controlled home while it is written, and so the flow diagram (task 14.2) can be attached to it as Attachment A.\n\nWHAT IS WRITTEN: scope, product description, intended use, the flow diagram Part, the CCPs as they are monitored today, and verification.\n\nWHAT IS NOT: Parts 4, 6 and 7 are marked NOT YET WRITTEN and name the workbook task that writes each. A plan that read as complete before its hazard analysis existed would be the defect the gap assessment found, repeated.\n\nThe number FSQM-016 was reserved for this plan in the remediation workbook on 2026-09-04, after FSQM-013 went to the Module 11 exemption analysis.\n\nNew (draft) - 2026-09-21 - Part 4 written (workbook task 14.1). The team is two positions, SQF Practitioner and Senior Site Manager, with engineering advice taken from equipment manufacturers. Positions are named, not people. Neither member holds a HACCP certificate yet, and Part 4 says so rather than implying a qualified team.\n\nNew (draft) - 2026-09-21 - Part 6 written (workbook task 14.4): a three-by-three likelihood and severity method, significant at a score of 6 or more, with fixed severity-3 hazards, evidence required for any severity-3 hazard called unlikely, and the step's own control set aside when judging likelihood. It is written before the hazard analysis because the gap assessment's finding against 2.4.3.8 was inconsistency, not absence.\n\nNew (draft) - 2026-09-21 - Part 6 re-laid out, wording unchanged in substance: each scale on one line with its levels numbered inline, and the fixed severity-3 hazards, the score rule and the evidence rule each on their own line. The body renders one list level only, so the scale levels had appeared as bullets alongside the rules they belong to.\n\nNew (draft) - 2026-09-21 - Part 6's likelihood and severity levels each on their own indented line, using the new sub-item line form (a line opening with the white bullet sits one level in under the bullet above it). Wording unchanged.\n\nNew (draft) - 2026-09-28 - ATTACHMENT A CORRECTED IN FIVE PLACES, found while the owner and the Senior Site Manager read the flow against the process.\n\n1. THE PAN RELEASE IS ITS OWN STEP. The molds are sprayed with Chef's Quality Pan Spray (soybean oil and soy lecithin) before the batter is deposited; the drawing had shown it only as an unnamed input to depositing. It is now step 5, 'Spray molds with pan release - done before, after or alongside mixing', which is how it is performed, and step 6 deposits into sprayed molds. The composition above names it.\n\n2. COOLING COMES BEFORE DEPANNING. The drawing had the product depanned as it left the oven. In fact the pans go straight onto the cooling racks and the product is turned out once it is cool. Day 1 now ends at 'Remove from oven, place the pans on the cooling racks', and Day 2 opens with step 9, 'Depan - turn the cooled product out of the pans'.\n\n3. THE COOL IS NOT NECESSARILY OVERNIGHT. Gabriela, 2026-09-28: what is required is cooling before depanning, and some batches are depanned later on Day 1 and some on Day 2. The delay now reads 'cool in the pans, covered, at room temperature on the racks, until cool enough to depan', with a note that depanning follows later on Day 1 or on Day 2. Writing it as a fixed overnight delay would have stated a control the site does not work to.\n\n4. MAKING THE SYRUP IS A CONDITIONAL STEP. Syrup is not made every run: step 10 runs only when no prepared syrup is in stock. Syrup kept for a later run is held ambient in a sealed container, and the dip step takes prepared syrup from stock as an input.\n\n5. THE SYRUP IS DIPPED AT ROOM TEMPERATURE. Syrup made on the day is cooled to room temperature before use, which the drawing carries as a delay off step 10; syrup taken from stock is already at room temperature. Step 11 reads 'Dip baked product in syrup at room temperature'. This matters to the hazard analysis in both directions: hot syrup on baked product is a different step from what the site performs, and a syrup cooling on the bench is itself a delay to be assessed.\n\nOPEN, AND ON THE DRAWING AS A GAP: stored syrup has NO HOLD LIMIT and NO LABEL today. How long it may be held, and what the container says, are decided in the hazard analysis (Part 7). A held food component with neither a limit nor a date is both a food safety question and a traceability one - a dipped batch cannot be tied to the syrup it was dipped in.\n\nThe diagram is now 20 steps. CCP 1 baking stays step 7; CCP 2 vacuum sealing moves from step 11 to step 13, and the scope box's rework sentence moved with it.\n\nALLERGEN: the spray's label declares CONTAINS: SOY, from the soy lecithin. Soy was already declared as an allergen of this product, and the owner confirmed on 2026-09-28 that the finished product label declares it, so nothing about the declaration changes. The pan spray and the bulk soybean oil are separate FRM-207 entries and are separate materials.\n\nTHIS IS WHAT CONFIRMING A FLOW DIAGRAM IS FOR (SQF 2.4.3.6): two things the drawing showed differently from how the floor works. The confirmation block on Attachment A is signed against this version, not the one before it.\n\nNew (draft) - 2026-10-01 - PART 7 WRITTEN (workbook tasks 14.5 and 14.6): the hazard analysis, step by step against the confirmed 20-step flow diagram, scored by the method in Part 6. With it every Part of this plan has text; none is marked NOT YET WRITTEN.\n\nIT IS A DRAFT FOR THE FOOD SAFETY TEAM, NOT THE TEAM'S ANALYSIS. The hazards, scores and controls were drafted from the flow diagram, the site's issued programs and what the site has said about its process. The team checks each line against the floor and adopts or changes it. No member of the team yet holds HACCP training (Part 4).\n\nWRITTEN BEFORE THE WATER ACTIVITY IS KNOWN. The product description had said the water activity was to be recorded before Part 7 was written. It has not been measured, so growth in the sealed product is scored as significant, as Part 6 requires of a severity 3 hazard with no evidence. The measurement needed is of the finished, sealed product - not of the cake before it is dipped.\n\nSYRUP (site, 2026-10-01): made two parts sugar to one part water, with rum added after heating; normally used within a few days; a hold limit of 30 days is set, sealed at room temperature; the container carries the date made and a lot code in the product's form. This closes the gap carried on the drawing since 2026-09-28. A supplier's specification for an invert syrup, giving six months in its original sealed packaging, was offered as the basis for a longer hold and was not used: it describes a different product in a different pack.\n\nWHAT THE ANALYSIS FOUND: four significant hazards without a control that is in place and proven - growth in the sealed product (water activity unmeasured), hard or sharp foreign material (no detection; a metal detector is planned), the bake (limits not validated, internal temperature not measured), and recontamination after the bake (environmental monitoring not in force). It also scores a failed seal as not significant, which puts CCP 2 in question for Part 8.\n\nOPEN BEFORE ISSUE: (1) the water activity, and pH, of the finished sealed product; (2) the team's review of every line; (3) which allergens other than wheat, milk, egg and soy are on the site; (4) that the liquid egg is pasteurised, from its pack - FRM-207 holds four materials so far; (5) whether a delivery of a brand that is not the one on FRM-207 is held until it has been checked - nothing requires it today; (6) the syrup: how much rum goes in, whether syrup already used for dipping may be kept, and writing the syrup's lot code on the lot record (FRM-520) of each batch dipped in it; the 30 days is the site's limit, not a measured one; (7) the metal detector; (8) validation of the bake; (9) FSQM-015; (10) the CCP decision in Part 8.\n\nNew (draft) - 2026-10-07 - PART 8 WRITTEN AS A DRAFT (workbook task 14.7): each significant hazard taken through the four questions of the Codex decision tree. CCP 1 baking stands. By the method sealing would not be a CCP; management keeps it as CCP 2 until the water activity is known and the team is trained. Foreign material has no control, so the process has to change: management's decision is a metal detector, not yet bought, which becomes a CCP when it is installed. Growth in the sealed product is not decided until the water activity is measured. Allergens, recontamination after the bake and labelling are controlled by programs and are not CCPs; two of those programs, FSQM-027 and FSQM-015, are still drafts. No member of the team holds HACCP training, so this is a draft for a trained team to confirm.\n\nNew (draft) - 2026-10-07 - CCP 2 wording corrected to what is done (site, 2026-10-07): every pouch is looked at as it comes off the sealer and again at boxing; the pull test is on one cooled pouch per lot at boxing, never on a warm seal; the gauge is read at set-up. The earlier text said every pouch was pull tested.\n\nNew - 2026-10-29 - ISSUED AS A LIMITED PLAN under D-14. Approved GJM, effective 2026-10-29. Replaces the HACCP plan of 23 June 2026, which is archived.\n\nWHY ISSUE NOW. Management decided (owner, 2026-10-29) to issue the plan rather than wait for every open item, because the June plan it replaces overstated what was proven, and this one states it. The open items are not hidden: they are a Part of the plan, Part 9 'Stated limitations at issue', each with its action, owner and date.\n\nWHAT CHANGED FROM THE DRAFT: Parts 7 and 8 no longer say they are a draft for the team - the team adopted them at issue, and they are reviewed again by the trained team within 30 days of the first HACCP certificate. The 'cannot be issued until' wording in Parts 7 and 8 now points to Part 9. The intended-use caution from the June plan is stated as standing. The flow diagram confirmation is described as done, with the signed sheet to attach. Part 9 is new; verification and review is now Part 10.\n\nOPEN AT ISSUE (Part 9): HACCP training for both team members; the trained team's review of Parts 7 and 8; water activity and pH of the finished, sealed product; validation of the bake and the internal temperature; the CCP 2 vacuum level and seal width; the metal detector; FSQM-027 and FSQM-015 still drafts; the signed flow diagram confirmation sheet; the 21 CFR 117 decision.\n\nSETTLED SINCE THE DRAFT'S OPEN LIST OF 2026-10-01: the brand-substitution hold (SOP-2.3.4 v4); the syrup - made on site on FRM-530 with a 30-day use-by, the rum added in the dunk tank and not kept in the syrup, and the syrup and rum lots written on the lot record FRM-520 (FSQM-021 v3).\n\nv2 - 2026-10-29 - SQF 2.4.3.17 ADDRESSED: the country of production and destination. Owner, 2026-10-29: the product is sold only in the United States today, the United Kingdom is planned, and yearly food sales are under $1 million. So the site is a qualified facility under the FDA Preventive Controls rule and follows its modified requirements (21 CFR 117.201): the biennial attestation, with this plan as its basis, and the facility's name and address on the label. Part 1 now says so, with what happens if the status is lost and before a first shipment to a new country. The Part 9 limitation 'decide 21 CFR 117 by 2027-03-31' is replaced by two checks due 2026-12-31: the label carries the facility's name and address, and the 2026 attestation was submitted with the registration renewal. 2.4.3.17 added to the clause references.\n\nv3 - 2026-10-29 - Label requirement corrected (Senior Site Manager, 2026-10-29). v2 said the label must show this facility's name and address under 21 CFR 117.201(e). That notice is required only of a qualified facility that attests to compliance with state or local law; this site attests to its food safety practices, so it does not apply. The label names the manufacturer, packer or distributor under 21 CFR 101.5 ('Manufactured by', 'Manufactured for' or 'Distributed by'). The Part 9 label check is removed; the attestation check stays, due 2026-12-31.\n\nv4 - 2026-10-29 - FSQM-015 Environmental Monitoring issued. The four lines that called it a draft now say it is issued, with its laboratory due by 2026-11-30 and its first round by 2027-01-31. FSQM-027 is still a draft.\n\nv5 - 2026-10-29 - FSQM-027 Allergen Management issued. The two lines that called it a draft now say it is issued, with its test kit due by 2026-11-30 and its validation swabs by 2027-01-31.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.4.3 Food Safety Plan, and 2.3.1.3. Codex Alimentarius, General Principles of Food Hygiene (CXC 1-1969), HACCP system and guidelines for its application.\n\nTHIS PLAN REPLACES THE HACCP PLAN OF 23 JUNE 2026, version 1.0, which was held as an unnumbered reference document with an unsigned approval page. It was archived, not deleted, when this plan was issued on 2026-10-29.\n\nFSQM-017 Validation and Verification Program - the verification schedule the CCP record reviews sit on.\nFSQM-039 Facility Layout and Product Flow - the floor layout and hygiene zoning; not the flow diagram.\nFSQM-015 Environmental Monitoring Program - depends on the water activity this plan records.\nFSQM-018 Non-Conforming Product and Equipment, and FSQM-009 Corrective and Preventive Action Program - deviation handling.\n\nThe product is subject to 21 CFR 117 (Preventive Controls for Human Food). The site is a qualified facility under it (21 CFR 117.3 and 117.201); how this plan meets it is in Part 1."}$jx$::jsonb,
       revision = 'v5', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FSQM-016' and status = 'active' and revision = 'v4';

update public.sop_documents set content = $jx${"scope": "Every element of the SQF System operated at this site, and every activity by which the effectiveness of those elements is established or confirmed.\n\nIt does not restate the controls it schedules, and it does not duplicate their records. Good Manufacturing Practices are FSQM-012 and FSQM-022; sanitation is FRM-901, FRM-902 and FRM-903 with the machine SSOPs beneath them; temperature monitoring is SOP-401 and FRM-401; retention sampling is FSQM-014; product release is FSQM-020; dispatch is FSQM-036; corrective action is FSQM-009. This program supplies the method, the responsibility, the criteria and the schedule.", "purpose": "To state the methods, responsibility and criteria by which the site validates that its food safety controls achieve the results required of them, and verifies that those controls are being operated; and to hold the master verification schedule listing every verification activity, its frequency, the position responsible for it and the record that evidences it. It satisfies the Validation and Effectiveness and Verification Activities elements of the SQF Food Safety Code: Food Manufacturing, Edition 9 (2.5.1 and 2.5.2), both of which are Mandatory.", "records": "This program creates no record of its own. The record of each verification activity is the form named against it in Part 6, held and retained by the program that defines that form.\nThe schedule itself is a record, and it is Part 6 of this document. It is amended by revising this document.\nThe annual review of this program is evidenced by its revision, as it is for every program in this document set.\nRetention of the activity records: as set by each owning program; none is shorter than two years, or the shelf life of the product plus twelve months, whichever is longer, on the basis FSQM-009 Part 10 states.", "procedure": ["This program states how the site validates that its food safety controls achieve what they are meant to achieve, and how it verifies that those controls are being operated. It holds the master verification schedule required by 2.5.2.2, which is set out in Part 6.", "> Validation and verification are different questions and this program keeps them apart. Validation asks whether a control WOULD work: is the method capable of the result claimed for it. Verification asks whether it DID: was it carried out, by whom, and does the record show it. Monitoring is neither - it is the doing itself, and it lives in the programs below rather than here.", "This program schedules and verifies the controls that other programs define. It does not restate them, and it does not create a record of its own where one already exists.", "• Good Manufacturing Practices are defined by FSQM-012 and monitored under FSQM-022, whose monthly full-site inspection is recorded on FRM-913.", "• Sanitation is scheduled by FRM-901, confirmed daily on FRM-903 and verified on FRM-902, with the machine SSOP logs FRM-909 to FRM-912 beneath them.", "• Temperature monitoring is SOP-401, and its monthly review on FRM-401 is already written as the verification that the automatic monitoring worked.", "• Retention sampling is FSQM-014 and FRM-703; product release is FSQM-020 and FRM-701; dispatch is FSQM-036 and FRM-801; glass and brittle plastic is FRM-907.", "• Corrective and preventive action is FSQM-009, recorded on FRM-007.", "> Naming them rather than absorbing them is the point. An umbrella program that restates the controls beneath it creates two versions of every rule, and the day they disagree is the day the document set stops being evidence of anything. What this program adds is the method, the responsibility, the criteria and the schedule.", "> The same reasoning governs the records. Every activity on the schedule in Part 6 is recorded on the form named against it, and this program issues no general-purpose verification form of its own. A catch-all record beside a purpose-built one produces two accounts of a single activity, and is weaker evidence than either.", "Good Manufacturing Practices shall be confirmed to achieve the results required of them, and the confirmation shall be recorded.", "• The monthly site inspection on FRM-913 examines each Module 11 subsection against the Code and records what was found, not merely that a look was taken.", "• Sanitation verification on FRM-902 confirms that cleaning achieved its result rather than that cleaning was performed, which is what FRM-903 already confirms.", "• Where an inspection or a verification finds a practice that is not achieving its result, the finding is raised under FSQM-009 and the practice is changed. A finding closed without a change is a finding that was not believed.", "> WHAT THIS SITE CANNOT CURRENTLY DO, stated plainly rather than implied. Confirming a hygiene practice by measurement - environmental swabbing, ATP, indicator organisms - requires analysis, and this site performs none: FSQM-014 records that there is no on-site laboratory, no external laboratory and no reliance on supplier certificates of analysis. Confirmation here therefore rests on inspection and on record review.", "> That is a real limit and it is not closed by wording it carefully. The deliverable that changes it is the environmental monitoring program for ready-to-eat product, which introduces sampling, pathogen and indicator selection, and trending. When it is issued, this Part is revised to cite it and the analytical limb of 2.5.1.1 i is met properly. Until then this program does not claim more than inspection can support.", "Critical food safety limits shall be reviewed at least annually, and re-validated or justified against a regulatory standard whenever they change or whenever the process they control changes.", "• A limit that is re-validated shall record the evidence relied on. A limit justified by reference to a regulatory standard shall record the standard.", "• Where a limit changes, the change shall be assessed under Part 4 before it takes effect.", "> WRITTEN CONDITIONALLY, AND ON PURPOSE. The limits this Part governs are those established by the food safety plan, FSQM-016 Food Safety Plan (HACCP) - Rum Cake, issued 2026-10-29 as a limited plan. It replaces the unnumbered HACCP plan of 23 June 2026, which is archived, and identifies two critical control points:", "• CCP 1 — Baking. Hazard: survival of Salmonella, Shiga toxin-producing E. coli and Listeria monocytogenes from the flour, egg and milk powder. Critical limits: oven at least 350°F for at least 27 minutes. The June 2026 plan also set an internal product temperature of at least 180°F at the end of the bake; the product is not probed today. Monitoring: every oven load.", "• CCP 2 — Vacuum sealing in pouches. Hazard: loss of package integrity, which admits microbial contamination and ends shelf stability. Critical limits: vacuum level to the equipment specification; no visible leak, channel, wrinkle across the seal, or partial seal, and no air in the pouch; and seal width to the equipment specification. Monitoring: a visual check of every pouch as it comes off the sealer, for seal defects and for air in the pouch. At boxing, once the seal is cool, every pouch is looked at again for lost vacuum and one pouch from each lot is pull tested. A pull test is not done on a warm seal.", "> Both points are monitored and recorded by the production operator: CCP 1 on FRM-507 CCP 1 Baking Monitoring Record, and CCP 2 on FRM-606 CCP 2 Vacuum Sealing Monitoring Record. The internal product temperature at CCP 1 is not monitored, and FRM-507 records that each production day rather than leaving the column blank. The limits are now established by a controlled document, but they are not yet validated: FSQM-016 Part 9 states, with dates, the validation of the bake (including the internal temperature) and the vacuum level and seal width for this site's sealer, which are not yet confirmed.", "> The annual review and re-validation of critical limits is therefore carried on the schedule as not yet implemented rather than as a review somebody is failing to do: until the limits are validated there is nothing to re-validate. It is activated when the bake is validated and the CCP 2 specification is confirmed (FSQM-016 Part 9). The cooling steps after the bake are not critical control points (FSQM-016 Parts 7 and 8).", "> Two limits are in force today and are governed by the programs that state them, because they are real whether or not a HACCP plan names them: the refrigerator and freezer limits in SOP-401, reviewed monthly on FRM-401, and the sanitizer concentration stated in FRM-903 and the SSOPs. NEITHER IS A CRITICAL CONTROL POINT. Recording them as though they were would be the opposite error to ignoring them, and would put a CCP in the document set that no hazard analysis ever identified.", "A change to a process or a procedure shall be assessed for its effect on food safety controls BEFORE it takes effect, and the assessment shall be recorded.", "• The triggers are: a new or reformulated product; a change of process step, equipment, ingredient, supplier, packaging or label; a change to the layout of the site; and a change to who performs a monitoring or verification role.", "• The assessment records what control the change touches, whether that control remains effective, and what was altered to keep it so.", "• Where a dedicated record governs the change it is used: label changes are FRM-601 and REP-603, a new supplier is FRM-202, a new material is FRM-207, and a change arising out of a corrective action is recorded on its FRM-007.", "> Every other change that can alter whether the product is safe - a new product or recipe, a changed process step or limit, new or modified equipment that touches the product - is assessed and approved on FRM-015 under FSQM-007 Change Management Program. That program also states which changes need no record beyond the revision of the document that describes them, and how a change of people is handled.", "> The order matters more than the paperwork. A control assessed after the change it exists to control has already failed to control it - the same reasoning FSQM-036 Part 3 applies to introducing temperature-controlled transport, and FSQM-014 Part 2 to introducing analysis.", "The monitoring of Good Manufacturing Practices, of critical control points and of other food safety controls shall be verified, and the person responsible for verifying shall authorize each verified record.", "• Verification confirms that monitoring was carried out as required, that its results were within limits, and that anything outside limits was acted on.", "• The verification signature on the record IS the authorization required by 2.5.2.1. FRM-903, FRM-913, FRM-902, FRM-401, FRM-701, FRM-507 and FRM-606 each carry one, and it is not repeated anywhere else.", "• A person shall not verify their own monitoring where a second qualified person is available. Where one is not, the record shall say so.", "> That last rule is written the way FSQM-004 had to be rewritten. An absolute separation requirement made a legitimate single-operator run non-compliant, and 11.2.5.7 asks for QUALIFIED personnel rather than independent ones. A rule the site cannot always follow is worse than a weaker one it can: the first thing that happens to it is that it is ignored.", "> A verification that leaves no signature is indistinguishable from one that did not happen. That is why 2.5.2.1 names authorization separately from verification, and why the schedule names a position against every activity rather than leaving it to whoever is free.", "> CRITICAL CONTROL POINTS ARE VERIFIED ON THEIR OWN RECORDS. The production operator records the monitoring of the two critical control points in the site's HACCP plan on FRM-507 for baking and FRM-606 for vacuum sealing. Each entry carries a required verification signature and is not submitted until the reviewer has checked it against the critical limits and confirmed that every deviation has a recorded action; that signature is the authorization 2.5.2.1 requires. The review is scheduled weekly in Part 6, one activity per record. What it cannot yet confirm is stated on the forms: the internal product temperature at CCP 1, which is not monitored, and the CCP 2 vacuum level and seal width against a specification not yet confirmed for this site's machine.", "The master verification schedule is set out below. It states every verification activity, the frequency at which it is completed, the position responsible for it, and the record that evidences it.", "• Site GMP and food safety inspection — Monthly — SQF Practitioner — FRM-913", "• Review of daily sanitation and pre-operational records — Weekly — Production Supervisor — FRM-903", "• Sanitation verification — Weekly — SQF Practitioner — FRM-902", "• Temperature monitoring record review — Monthly — SQF Practitioner — FRM-401", "• Retention sample review and disposal — When a sample on the shelf passes its discard date — SQF Practitioner — that sample's own entry on FRM-703", "• Finished product release record review — Weekly — SQF Practitioner — FRM-701", "• Dispatch and vehicle loading record review — Weekly — SQF Practitioner — FRM-801", "• CCP 1 baking monitoring record review — Weekly — SQF Practitioner — FRM-507", "• CCP 2 vacuum sealing monitoring record review — Weekly — SQF Practitioner — FRM-606", "• Glass and brittle plastic register check — Monthly — Production Supervisor — FRM-907", "• Review of open and overdue corrective actions — Monthly — SQF Practitioner — FRM-009, under \"Open corrective actions\"; each CAPA itself is recorded on FRM-007 and listed on REP-007", "• Customer complaint review and trending — Monthly — SQF Practitioner — FRM-009, under \"Complaints, incidents and recalls\"; the complaints themselves are reported on FRM-002 and listed on REP-003", "• Monthly SQF update to senior site management — Monthly — SQF Practitioner — FRM-009; the update required by 2.1.2.2 and management's response to it, distinct from the annual management review above", "• Management review of the SQF System — Annually — Senior Site Management — FRM-001", "• Blackout period declaration to the certification body — Annually — Senior Site Management — FRM-006; dated from the period the declaration in force covers, not from when it was filed, and raised 90 days ahead of the next period", "• Annual review and re-validation of critical food safety limits — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting validation of the critical limits (FSQM-016 Part 9)", "• Annual review of the Validation and Verification Program — Annually — SQF Practitioner — evidenced by the revision of FSQM-017", "• Calibration of measuring and monitoring equipment — Monthly — SQF Practitioner — FRM-705", "• Preventive maintenance check of equipment and building — Monthly — SQF Practitioner — FRM-508", "• Backflow prevention device testing — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting D-31 Water and Utilities Program", "• Potable water microbiological and chemical analysis — Annually — SQF Practitioner — no record; not yet performed. NOT YET IMPLEMENTED — awaiting D-31 Water and Utilities Program", "• Internal audit of the SQF System — Quarterly — SQF Practitioner — FRM-010", "• Traceability and mock recall test — Annually — SQF Practitioner — FRM-012", "• Crisis management plan review and test — Annually, before 1 June — Senior Site Management — FRM-013", "• Environmental monitoring sampling round — Every four months — SQF Practitioner — FRM-706", "• Food defense and food fraud review and test — Annually — SQF Practitioner — FRM-014", "• Allergen cleaning verification swab — Annually, one changeover clean on each machine — SQF Practitioner — FRM-916", "> The schedule is maintained in the Team Portal under Compliance, where it is the same record the reminder system reads. Adding, retiring or re-timing an activity is done there, and the list above is this program's copy of it as at the effective date of this revision. A change to the schedule is therefore a revision of this program, and the annual review in Part 10 is the occasion that catches it.", "> AN ACTIVITY MARKED NOT YET IMPLEMENTED IS SCHEDULED AND IS NOT BEING PERFORMED, because the program that governs it has not been issued. Each names the deliverable that will bring it into force, no reminder is raised for it, and no record is expected against it.", "> Listing activities the site is not yet performing is deliberate and is the harder of the two options. Omitting them would produce a schedule that looked complete and was not, and an auditor comparing it against the Code would find the gaps anyway - having also learned that the schedule does not show them. Stating them is the position that survives being read carefully.", "Verification activities that have fallen due shall be raised to the whole team within the Team Portal, labelled with the position responsible for each.", "• The prompt is raised twice each working day from the schedule. Nothing is routed to an individual: the schedule names the responsible position, and the notification carries that label.", "• A prompt is cleared for the whole team by whoever acts on it, and the clearing records who and when.", "> A NOTIFICATION IS A PROMPT, NOT A RECORD. Clearing one does not perform the activity and is not evidence that it was performed. The record is the entry on the form the notification links to. The name and time against a cleared prompt show only that somebody took the prompt, and this program does not treat them as verification.", "> The distinction is worth defending because the failure it prevents is quiet. A feed that feels like a checklist becomes one that gets ticked, and a system whose evidence is a list of dismissals has replaced the work with the reminder about the work.", "Where a verification activity finds that a control is not effective, or was not carried out, the finding shall be raised under FSQM-009 and its corrective action recorded on FRM-007.", "• The activity that found it is still recorded as completed. A verification that finds a problem has succeeded, not failed.", "> Recording the failure and the verification separately keeps both true. Marking a verification incomplete because it found something would mean the schedule showed the activity as outstanding, which would raise it again the next morning and lose the finding in the noise.", "Records of verification activities are the records named against each activity in Part 6, held and retained by the programs that define them. This program creates no record of its own.", "The SQF Practitioner shall review this program at least annually, and whenever a program it schedules is issued, amended or withdrawn. The review is evidenced by the revision of this document.", "> That is how every program in this document set evidences its annual review, and it is why this one does not carry a review form. The schedule is the part that goes stale, and it goes stale quietly: an activity keeps its place on the list long after the program that governed it changed. The annual review is also the occasion on which the not yet implemented activities are re-examined, because each becomes real the day its deliverable is issued and nothing else will announce that to this document."], "definitions": "Validation: establishing that a control is capable of achieving the result claimed for it. It asks whether the control WOULD work.\n\nVerification: confirming that a control was operated as required and that its records show it. It asks whether the control DID work.\n\nMonitoring: carrying out the control and recording the result at the time. Monitoring is neither validation nor verification, and it lives in the program that defines the control.\n\nVerification activity: one scheduled task in Part 6, with a frequency, a responsible position and a named record.\n\nNot yet implemented: the status of a scheduled activity whose governing program has not been issued. The activity is listed and is not being performed.", "responsibility": "SQF Practitioner — owns this program and the schedule. Performs or assigns each verification activity, authorizes verified records, and raises findings under FSQM-009.\nProduction Supervisor — performs the verification activities assigned to that position, and ensures monitoring is carried out so that there is something to verify.\nProduction staff — carry out the monitoring that these activities verify, and complete the records that are its evidence.\nAdmin — maintains the records and their retention.\nSenior Site Management — provides the resources the schedule requires, reviews the system under 2.1.2, and is the authority for any decision to change an activity's frequency.", "form_references": "FRM-913 GMP / Food Safety Inspection Record; FRM-903 Daily Sanitation, Pre-Operation & Release Record; FRM-902 Sanitation Verification Log; FRM-901 Master Sanitation Schedule; FRM-401 Temperature Monitoring Review; FRM-703 Retention Sample Log; FRM-701 Finished Product Release Record; FRM-801 Dispatch and Vehicle Loading Record; FRM-907 Glass & Brittle Plastic Register; FRM-007 Corrective & Preventive Action Report; FRM-002 Customer Complaint Report; FRM-001 Management Review Record; FRM-507 CCP 1 Baking Monitoring Record; FRM-606 CCP 2 Vacuum Sealing Monitoring Record; FRM-705 Calibration Directory and Check Record; FRM-508 Monthly Maintenance Check; FRM-010 Internal Audit Record; FRM-015 Change Assessment Record", "revision_history": "v17 - 2026-10-16 - The retention sample reminder is raised when a sample is due.\n\nPart 6 listed the retention sample review and disposal as weekly, evidenced by FRM-703. One FRM-703 is one sample and is submitted only when that sample leaves the shelf, so while every sample was within its period the weekly reminder could never be discharged, and the only way to clear it was to record a sample as gone that was still on the shelf. FSQM-014 asks for no weekly review: a sample is kept until thirty days after the date on its pack and its disposal is recorded on FRM-703 when it leaves. The activity is now raised when a sample on the shelf passes its discard date, links to that sample, and is discharged by recording its disposal (owner's decision, 2026-10-16). The position responsible is unchanged.\n\nv16 - 2026-10-16 - The monthly CAPA review is evidenced by the monthly SQF update.\n\nPart 6 listed the review of open and overdue corrective actions against FRM-007. FRM-007 is the report of one corrective action, so it cannot show that the month's corrective actions were reviewed, and the schedule's reminder could never be discharged - the same fault v15 corrected for the complaint review. The review is done at the monthly SQF update and recorded on FRM-009 under \"Open corrective actions\", against the CAPA log REP-007; FSQM-009 v2 says so, and the schedule line and the reminder now do too (owner's decision, 2026-10-16). Frequency and the position responsible are unchanged.\n\nv15 - 2026-10-12 - The monthly complaint review is evidenced by the monthly SQF update.\n\nPart 6 listed the customer complaint review and trending against FRM-002. FRM-002 is the report of one complaint, so it cannot show that a month's complaints were reviewed, and the schedule's reminder could never be discharged. The review is done at the monthly SQF update and recorded on FRM-009 under \"Complaints, incidents and recalls\", against the log REP-003; the schedule line and the reminder now say so (owner's decision, 2026-10-12). Frequency and the position responsible are unchanged.\n\nRev New — written 2026-09-10 against SQF Food Safety Code: Food Manufacturing, Edition 9, 2.5.1 Validation and Effectiveness and 2.5.2 Verification Activities. ISSUED 2026-09-10, approved GJM (Senior Site Management), effective 2026-09-10.\n\nWHY IT EXISTS. The gap assessment scored 2.5.1.1, 2.5.2.1 and 2.5.2.2 and no controlled document covered validation or verification as a subject. Individual programs verified themselves - FSQM-022's monthly inspection, FRM-401's monthly review - but nothing held the schedule 2.5.2.2 requires or stated the method 2.5.1.1 and 2.5.2.1 require. Both clauses are Mandatory.\n\nIT SCHEDULES RATHER THAN RESTATES. Part 1 names every program whose controls this one verifies and defers to each. An umbrella that restates the controls beneath it creates two versions of every rule, and the day they disagree the document set stops being evidence. FSQM-036 Part 7 took the same approach to unloading, pointing back at FRM-301 rather than building a second receiving form.\n\nAMENDED 2026-09-10, BEFORE ISSUE — FRM-008 WAS REDUNDANT AND HAS BEEN DELETED. This program was first drafted with a companion form: FRM-008, carrying the printed schedule and a general-purpose verification activity record. The owner questioned whether that record was doing any work, and it was not. Eleven of the thirteen active activities already record on their own form. The two that did not dissolved on inspection: no active FSQM programme in this document set records its annual review on a form - the revision is the evidence, in all eight of them - and the annual re-validation of critical food safety limits belongs with the food safety plan that establishes those limits, which does not exist, so that activity is now carried as not yet implemented alongside CCP record review for the same reason.\n\nWith the record section serving nothing, what remained was a form with a printed table and nowhere to write. 2.5.2.2 asks the PROGRAMME to have a verification schedule, so the schedule became Part 6 of this document and FRM-008 was deleted. One document instead of two, and no second copy of the schedule to keep in step. FRM-008 returns to being an unused number.\n\nThe general-purpose record was also the wrong shape on its own terms. A catch-all beside a purpose-built record produces two accounts of one activity, and invites being filled in alongside the real form rather than instead of it. Part 1 now says so in terms.\n\nTHE ANNUAL REVIEW OF THIS PROGRAM is evidenced by its revision, which is both how every other programme here does it and something the application already records in sop_document_history. The schedule reads that history to know when the review last happened, so the activity is still prompted without a form existing to carry it.\n\n\n\nSETTLED AT ISSUE — 2026-09-10:\n\n1. WHO APPROVES. Senior Site Management, GJM. This program appoints verification responsibilities across every position including the SQF Practitioner's own, so approval by the role it assigns work to would have been the appointee approving their own appointment - the same reasoning FSQM-004 records.\n\n2. THE FREQUENCIES IN PART 6 ARE THE SITE'S, FROM THIS DATE. They were seeded as proposals to give the schedule a working shape and were issued without a separate confirmation pass, which is recorded here rather than glossed: a reader should know that the cadences were adopted by issuing the document rather than derived one by one from a risk assessment. They are amended by revising this program, the schedule page is where the change is made, and the annual review in Part 10 is the occasion that re-examines them. A frequency that turns out to be wrong is a revision, not a non-conformance.\n\n3. THE ANALYTICAL LIMB OF 2.5.1.1 i IS NOT MET, AND THIS PROGRAM DOES NOT CLAIM IT. Confirming that Good Manufacturing Practices achieve their result normally rests on measurement, and this site performs no analysis at all - no laboratory, no external laboratory, no reliance on supplier certificates of analysis. Part 2 says so and rests the confirmation on inspection and record review. The environmental monitoring program for ready-to-eat product is the deliverable that changes it, and Part 2 is revised when that is issued. This is a standing limitation of the program as issued, not an open action.\n\n4. PART 3 HAS NOTHING TO BITE ON YET, for the same kind of reason. The critical limits it governs are those a food safety plan establishes, and the site has no HACCP plan under document control and no critical control points defined. The rule stands; the activity is carried on the schedule as not yet implemented; and the two limits that ARE real today are named in Part 3 together with the statement that neither is a CCP.\n\nWHAT THIS CLOSES. 2.5.2.1 and 2.5.2.2 are in force from this date. 2.5.1.1 is met in part - limb iii by Part 4, limbs i and ii as far as a site with no analysis and no food safety plan can meet them, with both gaps stated on the document. Recording that as a full closure would be closing a Mandatory clause on evidence that does not exist.\n\nREVISED 2026-09-11 — v2, approved GJM (Senior Site Management), effective 2026-09-11. PART 3 WAS WRONG ABOUT CRITICAL CONTROL POINTS, AND PART 5 CLAIMED MORE THAN THE SITE DOES.\n\nAs issued, Part 3 said the site had no critical control points defined, and item 4 of the settled block above repeats it. That came from searching the text of every controlled document, and the search never opened attached files. The site's HACCP plan is held in the document library as an attached PDF on an unnumbered reference document, and it identifies five critical control points: baking, cooling from the oven, cooling before covering, sealing, and sealing leak. The plan has no document number and no approval, so it is not under document control, and that half of the statement stood. The other half did not.\n\nTHE FIVE POINTS ARE MONITORED BUT NOT RECORDED, confirmed on 2026-09-11. That changes two Parts. Part 3 now names the five points, and states that no critical limit for them is established by a controlled document and that there is no record to review a limit against. Part 5 gains a paragraph stating that the verification of critical control point monitoring required by 2.5.2.1 is not performed, because verification confirms a record and there is none. The two schedule activities that depend on it, CCP monitoring record review and the annual review and re-validation of critical food safety limits, stay not yet implemented, and their descriptions on the schedule are corrected to say why.\n\nWHAT THIS CHANGES ABOUT WHAT THE PROGRAM CLOSES. At issue 2.5.2.1 was recorded as in force. It is in force for Good Manufacturing Practices and for the other food safety controls named in Part 1, and NOT for critical control points. Unlike the analytical limb of 2.5.1.1, this is an open action rather than a standing limitation: the points are already monitored, and what is missing is the record. It closes when the food safety plan is brought under document control with a monitoring record for each point. 2.5.1.1 remains met in part, as issued.\n\nThis revision is a correction, not the annual review of the program in Part 10, although the application records it as a revision and the schedule dates the next review from it.\n\nREVISED 2026-09-11 — v3, approved GJM (Senior Site Management), effective 2026-09-11. THE v2 CORRECTION COUNTED THE CRITICAL CONTROL POINTS WRONGLY.\n\nv2 listed five critical control points: baking, cooling from the oven, cooling before covering, sealing, and sealing leak. That list was not taken from the plan's control chart, and the plan was read in full for this revision. It defines two: CCP 1, baking, and CCP 2, vacuum sealing in pouches. Sealing and sealing leak are the biological and the physical hazard of the same step, CCP 2.\n\nTHE TWO COOLING STEPS ARE NOT CRITICAL CONTROL POINTS, although one table in the plan says they are. The plan's hazard analysis marks temperature control on the racks, and cooling to room temperature before covering, as CCP 1 and calls them kill steps. Its flow diagram marks only baking and vacuum sealing, and its control chart sets critical limits and monitoring only for those two. Cooling destroys nothing, and a step with no critical limit cannot be operated as a critical control point, so this program follows the diagram and the control chart and leaves the discrepancy to be corrected in the plan.\n\nv2 ALSO SAID THE PLAN HAS NO APPROVAL. Its cover names an approver and a version. It carries no document number, it is not under document control, and its approval page is unsigned, so the conclusion stood: no critical limit is established by a controlled document. Part 3 now says so precisely.\n\nPART 3 NOW LISTS BOTH POINTS with the hazard, critical limits and monitoring the plan states for each, and records the limits the plan has not settled: the vacuum level and seal width, given only as the equipment specification, and the validation of the bake, for which the plan recommends a lethality study rather than relying on one. Part 5 and the two schedule descriptions now say two points, not five. Nothing else changes: 2.5.2.1 remains in force for Good Manufacturing Practices and the other controls and not for critical control points, as v2 recorded, and both schedule activities stay not yet implemented.\n\nREVISED 2026-09-11 — v4, approved GJM (Senior Site Management), effective 2026-09-11. THE CRITICAL CONTROL POINTS ARE NOW RECORDED.\n\nFRM-507 CCP 1 Baking Monitoring Record and FRM-606 CCP 2 Vacuum Sealing Monitoring Record were issued on the same date. The production operator records every oven load and every sealing check on them, and each entry carries a required verification signature, so the monitoring that v2 and v3 recorded as unrecorded now has a record, and the verification 2.5.2.1 requires can be performed and authorized.\n\nPart 3 now names the two forms and states the one limit still not monitored, the internal product temperature at CCP 1, which is not probed. Part 5's paragraph on critical control points describes the verification rather than its absence, and its list of records that carry a verification signature adds FRM-507 and FRM-606. Part 6 replaces the single not-yet-implemented CCP monitoring record review with two weekly activities, one per record, first due 18 September 2026. Each is in force from this date and raises its reminder like every other active activity.\n\nWHAT THIS CHANGES ABOUT WHAT THE PROGRAM CLOSES. 2.5.2.1 is now in force for critical control points as well as for Good Manufacturing Practices and the other controls, with two limitations stated on the forms: the internal product temperature at CCP 1 is not monitored, so it cannot be verified, and the CCP 2 vacuum level and seal width are verified against an equipment specification not yet confirmed for this site's machine. The annual review and re-validation of critical food safety limits stays not yet implemented, because the limits are not yet established by a controlled document or validated. 2.5.1.1 remains met in part.\n\nSOP-505 is revised on the same date so that oven temperature and bake time are recorded on FRM-507 rather than on the batch sheet, which never held them.\n\nv5 — 2026-09-16 — The annual compressed air quality analysis retired from the schedule, under D-32.\n\nPart 6 carried \"Compressed air quality analysis — Annually — NOT YET IMPLEMENTED — awaiting D-32 Compressed Air and Gases\". D-32 is answered. The site's compressed air operates pneumatic equipment, where it contacts no food and no food-contact surface, and its one other use — clearing film scraps from the flow wrapper — is now performed only with the film unloaded and the table cleared, under SOP-605 v2, and is carried in FSQM-013 as a category C alternative control. 11.5.5.2's testing obligation is scoped to air that contacts food or food-contact surfaces; with that use controlled there is no air in scope to test, and an annual analysis would be a record of nothing.\n\nThe activity is RETIRED on the schedule rather than deleted, which is how this program treats an activity that stops applying, and the line is removed from this Part. The obligation returns the moment compressed air is put into contact with product or a food-contact surface — a new machine, a blow-off drying step, or the flow wrapper being cleaned with film loaded. That is a change the annual review in Part 7 is meant to catch, and it re-opens the activity rather than waiting for the review after it.\n\nv6 — 2026-09-16 — The blackout period declaration added to the schedule, under D-05.\n\nSQF 2.1.1.8 requires senior site management to designate defined blackout periods and to submit them, with their justification, to the certification body at least one month before the sixty-day unannounced re-certification window opens. FRM-006 Blackout Period Declaration is issued with this revision as the record of that designation, and the activity joins Part 6.\n\nIT IS DATED DIFFERENTLY FROM EVERY OTHER ACTIVITY ON THIS SCHEDULE, AND DELIBERATELY SO. The rest are \"do it again a period after the last time you did it\". A blackout declaration states the period it covers, so filing it early or late says nothing about when it expires. Anchored on the filing date, a declaration signed in October for the following calendar year would come due the following October — ten months after the site was already covered — and one signed late would push its own expiry out and let the site run uncovered without the schedule noticing. It is therefore dated from the last day the declaration in force covers, and raised ninety days before the next period begins: enough notice to agree the dates, sign them and send them.\n\nNO DECLARATION HAS BEEN FILED YET, so the activity will be raised as never recorded at the next run of the reminder job. That is the intended prompt and not a fault — 2.1.1.8 is open until senior site management files one.\n\nTHE SUBMISSION LIMB REMAINS OPEN, and it is not a matter of scheduling. No certification body is engaged and no certificate is held, so there is nothing to submit to and no sixty-day window to count back from. FRM-006 Section 5 stays blank until there is one, and says so on its face.\n\nv7 — 2026-09-16 — The monthly SQF update added to the schedule, under D-06.\n\nSQF 2.1.2.2 requires the SQF Practitioner to update senior site management at least monthly on matters affecting the SQF System, and for the update and management's response to be documented. FRM-009 Monthly SQF Update Record is issued with this revision as that record, governed by FSQM-005, and the activity joins Part 6.\n\nIT WAS ASSESSED COMPLIANT AT THE GAP ASSESSMENT AND WAS NOT. The management review procedure then in draft said the monthly update was recorded in a \"Flash Report\", and no such report exists anywhere in this system. The rewritten FSQM-005 first replaced that with minutes \"retained with the management review records\", which named no form and nothing to prompt it — the same weakness one level less obvious, and caught on review before issue. FRM-009 is the answer to it: a short record, on the schedule, that prompts itself.\n\nTHE ACTIVITY WILL READ AS NEVER RECORDED until the first entry is submitted. That is the prompt working rather than a fault, and it is honest: the monthly meeting has been happening without a retained record for as long as the site has been holding it.\n\nv8 — 2026-09-21 — Calibration brought into force under D-28. FSQM-030 Calibration Program and FRM-705 Calibration Directory and Check Record are issued, so the calibration activity in Part 6 moves from NOT YET IMPLEMENTED to active: monthly, SQF Practitioner, evidenced by FRM-705. It was carried as annual while no program existed; FSQM-030 sets it monthly, one session covering every device on the directory. First due 2026-10-21, a month after issue, so the 25 lb certified test weight can be bought before the first check. Nothing else in the schedule changes.\n\nv9 — 2026-09-21 — Preventive maintenance check added to Part 6 at the owner's request, so the monthly FRM-508 check is prompted by the reminder system like the other monthly activities. Carried as NOT YET IMPLEMENTED until FSQM-029 and FRM-508 are issued under D-26, when it becomes active against FRM-508. Nothing else in the schedule changes.\n\nv10 — 2026-09-21 — Preventive maintenance brought into force under D-26. FSQM-029 Preventive Maintenance Program, FRM-508 Monthly Maintenance Check and FRM-509 Maintenance and Repair Record are issued, so the preventive maintenance check in Part 6 moves from NOT YET IMPLEMENTED to active: monthly, SQF Practitioner, evidenced by FRM-508. First due 2026-10-21, a month after issue. Nothing else in the schedule changes.\n\nv11 — 2026-10-01 — Internal audit brought into force under D-19. FSQM-038 Internal Audit Program and FRM-010 Internal Audit Record are issued, so the internal audit in Part 6 moves from NOT YET IMPLEMENTED to active: quarterly, evidenced by FRM-010. The SQF Practitioner keeps the audit plan on schedule; the audits themselves are carried out by the Internal Auditor appointed under FSQM-038. First raised 2026-12-01 for the Q4 2026 audit. Nothing else in the schedule changes.\n\nv12 — 2026-10-05 — Part 4 revised under D-04. FSQM-007 Change Management Program and FRM-015 Change Assessment Record are issued, so Part 4 no longer says there is no general change-assessment record: it names them, and adds FRM-202 and FRM-207 to the dedicated records. The rule itself - assess before the change takes effect - is unchanged, and so is the schedule.\n\nv13 — 2026-10-07 — Recall and crisis brought into force under D-21. FSQM-023 Product Withdrawal and Recall Program and FSQM-024 Crisis Management Plan are issued with their records, and FSQM-021 Product Identification and Traceability Program was issued on 2026-10-06. In Part 6 the traceability and mock recall test moves from NOT YET IMPLEMENTED to active: yearly, evidenced by FRM-012, first due 2026-12-31. One activity is added: the crisis management plan review and test, yearly before 1 June, Senior Site Management, evidenced by FRM-013, first due 2027-05-31. Nothing else in the schedule changes.\n\nv14 — 2026-10-07 — CCP 2 monitoring stated as it is performed. Management's decision: every pouch is looked at as it comes off the sealer, for seal defects and for air in the pouch; at boxing, once the seal is cool, every pouch is looked at again and one pouch from each lot is pull tested. The June 2026 plan's hourly pull test at the sealer is withdrawn - a warm seal can be pulled open by the test itself - and so is its gauge check on every cycle, which was not being performed. Recorded on FRM-606 v2. The record, the weekly review and the schedule are unchanged.\n\nv18 — 2026-10-29 — The food safety plan named. FSQM-016 Food Safety Plan (HACCP) - Rum Cake was issued on 2026-10-29 as a limited plan and the unnumbered June 2026 plan was archived, so Part 1 now names FSQM-016 in place of it. CCP 1 is stated as FSQM-016 states it. The limits are now under document control but not yet validated; the re-validation activity stays not yet implemented, now awaiting FSQM-016 Part 9 rather than D-14. The note about the June plan's cooling steps is replaced by a reference to FSQM-016 Parts 7 and 8. The records, the weekly reviews and the rest of the schedule are unchanged.\n\nv19 — 2026-10-29 — The environmental monitoring sampling round added to the schedule, with FSQM-015's issue: every four months, SQF Practitioner, evidenced by FRM-706, first due 2027-01-31. Nothing else in the schedule changes.\n\nv20 — 2026-10-29 — The yearly food defense and food fraud review and test added to the schedule, with the issue of FSQM-025 and FSQM-026: annually, SQF Practitioner, evidenced by FRM-014, first due 2027-01-31. Nothing else in the schedule changes.\n\nv21 — 2026-10-29 — The yearly allergen cleaning verification swab added to the schedule, with the issue of FSQM-027: one changeover clean on each machine, swabbed with the allergen test kit, SQF Practitioner, evidenced by FRM-916, first due 2027-01-31 (when the validation swabs are due). Nothing else in the schedule changes.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9.\n2.5.1 Validation and Effectiveness (MANDATORY). 2.5.1.1 requires documented and implemented methods, responsibility and criteria for ensuring the effectiveness of all applicable elements of the SQF System, validating that (i) Good Manufacturing Practices achieve the required results, (ii) critical food safety limits are reviewed annually and re-validated or justified when changes occur, and (iii) changes to processes or procedures are assessed for continued control. Parts 2, 3 and 4 respectively.\n2.5.2 Verification Activities (MANDATORY). 2.5.2.1 requires documented and implemented methods, responsibility and criteria for verifying the monitoring of GMPs, critical control points and other food safety controls, and requires that the personnel responsible for verifying monitoring authorize each verified record — Part 5. 2.5.2.2 requires a verification schedule stating the activities, their frequency and the person responsible, and that records of verification are maintained — Part 6 is the schedule, and Part 9 states where the records are held.\n2.5.3 Corrective and Preventative Action, and FSQM-009 — where a failed verification goes. This program routes to it and does not restate it.\n2.5.4.3 Regular inspections of site and equipment, and FSQM-022 — the monthly Module 11 inspection this program schedules and relies on, but does not define.\n2.1.2 Management Review — the annual review this program schedules on FRM-001."}$jx$::jsonb,
       revision = 'v21', approved_by = 'GJM', effective_date = date '2026-10-29'
 where sop_number = 'FSQM-017' and status = 'active' and revision = 'v20';

insert into public.verification_schedule
  (activity_key, activity, description, frequency_unit, frequency_count, responsible_position, evidence_kind,
   evidence_document_number, owning_program, sqf_reference, lead_days, grace_days, first_due_on, status, sort_order)
values
  ('allergen_swab_verification', 'Allergen cleaning verification swab',
   'One changeover clean on each machine, after a nut product, swabbed with the allergen test kit before the next use and recorded on FRM-916 (FSQM-027). The first entries are the validation swabs, due by 2027-01-31.',
   'year', 1, 'SQF Practitioner', 'form_entry', 'FRM-916', 'FSQM-027', '2.8.1.5', 30, 30, date '2027-01-31', 'active', 275);

do $verify$
declare c jsonb;
begin
  select content into c from public.sop_documents where sop_number = 'FSQM-027' and status = 'active' and approved_by = 'GJM';
  if c is null then raise exception 'FSQM-027 was not issued.'; end if;
  if jsonb_array_length(c->'procedure') <> 54 then raise exception 'FSQM-027 has % lines.', jsonb_array_length(c->'procedure'); end if;
  if c->'not_applicable'->0->>'clause' <> '2.8.1.11' then raise exception 'the 2.8.1.11 declaration is missing.'; end if;
  if not exists (select 1 from public.sop_documents where sop_number = 'FRM-916' and status = 'active') then raise exception 'FRM-916 was not issued.'; end if;
  if exists (select 1 from public.sop_documents where sop_number = 'SOP-204' and status <> 'archived') then raise exception 'SOP-204 was not archived.'; end if;
  if (select revision from public.sop_documents where sop_number = 'FSQM-016') <> 'v5' then raise exception 'FSQM-016 not revised.'; end if;
  if (select revision from public.sop_documents where sop_number = 'FSQM-017') <> 'v21' then raise exception 'FSQM-017 not revised.'; end if;
  if not exists (select 1 from public.verification_schedule where activity_key = 'allergen_swab_verification' and status = 'active') then raise exception 'schedule row missing.'; end if;
end $verify$;

commit;
